/**
 * Builds the REAL Hono application for route-level tests: the same buildApp
 * the entrypoint uses, over an in-memory store, secret store, and PIN auth —
 * no port, no filesystem database, no module-level side effects. Tests drive
 * it with app.request() and a genuine signed-in session cookie.
 */

import { join } from "node:path";
import { tmpdir } from "node:os";
import type { Hono } from "hono";
import type { Container } from "../src/composition.ts";
import { loadConfig } from "../src/platform/config.ts";
import { TailscalePinAuth, LOCAL_USER_ID } from "../src/platform/auth/local.ts";
import { HmacSessionCodec } from "../src/platform/auth/session.ts";
import { FileAttemptTracker, type AttemptTracker } from "../src/platform/auth/attempts.ts";
import { buildApp } from "../src/server/app.ts";
import { MemoryStore } from "./penny-memory-store.ts";
import { MemorySecretStore, FIXED_SESSION_KEY } from "./helpers.ts";

export const TEST_PIN = "8421";
export { LOCAL_USER_ID };

export interface TestApp {
  readonly app: Hono;
  readonly container: Container;
  readonly store: MemoryStore;
  readonly secrets: MemorySecretStore;
  /** Sign in with the test PIN and return the Cookie header for follow-ups. */
  signIn(): Promise<string>;
}

export interface MakeTestAppOptions {
  readonly attempts?: AttemptTracker;
  readonly timezone?: string;
}

export async function makeTestApp(options: MakeTestAppOptions = {}): Promise<TestApp> {
  const store = new MemoryStore();
  const secrets = new MemorySecretStore();
  await secrets.set(LOCAL_USER_ID, "auth_pin", TEST_PIN);
  const auth = new TailscalePinAuth(secrets, new HmacSessionCodec(FIXED_SESSION_KEY));
  const config = loadConfig({
    DEPLOY_MODE: "local",
    HOME: tmpdir(),
    ...(options.timezone !== undefined ? { PENNY_TIMEZONE: options.timezone } : {}),
  });
  const container: Container = { config, store, secrets, auth };
  const attempts =
    options.attempts ??
    new FileAttemptTracker({ path: join(tmpdir(), `penny-attempts-${crypto.randomUUID()}.json`) });
  const app = buildApp(container, { attempts, serveWeb: false });

  const signIn = async (): Promise<string> => {
    const res = await app.request("/api/auth/signin", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ kind: "pin", pin: TEST_PIN }),
    });
    if (res.status !== 200) throw new Error(`test sign-in failed: ${res.status}`);
    const setCookie = res.headers.get("set-cookie");
    if (!setCookie) throw new Error("test sign-in returned no cookie");
    return setCookie.split(";")[0]!;
  };

  return { app, container, store, secrets, signIn };
}

/** JSON POST with an optional session cookie. */
export function postJson(app: Hono, path: string, body: unknown, cookie?: string): Promise<Response> {
  return Promise.resolve(
    app.request(path, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        ...(cookie ? { cookie } : {}),
      },
      body: JSON.stringify(body),
    }),
  );
}

