/**
 * Effective-dated budget versions (the budget chronology). Pure helpers over
 * BudgetTemplate lines, mirroring the effective-dated mappings pattern the
 * category→envelope resolution uses (ISC-19, src/envelope/spend.ts).
 *
 * DAY-WEIGHTED PRORATION (owner decision, 2026-07-16): a line contributes to
 * every month M where month(effectiveFrom) <= M <= month(effectiveTo ?? infinity),
 * and its contribution is prorated by the days of M its effective window
 * actually covers:
 *
 *   contribution = round(amountCents * activeDays / daysInMonth)
 *
 * where activeDays counts the days of M inside [effectiveFrom, effectiveTo ?? open]
 * and daysInMonth is the real calendar length (28/29/30/31, leap-Feb correct).
 * A line covering the whole month contributes EXACTLY amountCents (activeDays ==
 * daysInMonth), so full-month resolution is unchanged from the original
 * month-bucket rule. The owner's example: $500/mo through 14 Jul + $600/mo from
 * 15 Jul gives July round(50000*14/31) + round(60000*17/31) = 55484 (~$554.84).
 * amountCents is already the monthly equivalent for every cadence (the `period`
 * field is a display label — see contract.ts BudgetVersionView), so proration
 * scales it directly with no cadence maths.
 *
 * A month's budget for an envelope is the SUM of all contributing lines'
 * prorated amounts, so two OPEN versions both covering the full month still
 * fully combine (the original overlap-sums rule is intact). A legacy line with
 * no dates reads as effectiveFrom '1970-01-01' / open-ended, which resolves
 * identically to the pre-versioning template for every month.
 *
 * No I/O and no clock reads: callers pass the month (and "now") explicitly, so
 * the timezone-correct current period stays derived from src/platform/time.ts
 * at the boundary.
 */

import type { BudgetTemplate, IncomeEnvelope, Period } from "../domain/types.ts";
import { comparePeriods, monthBounds, periodOfDate } from "../envelope/period.ts";

/** The default effectiveFrom for legacy lines written before versioning. */
export const OPEN_EFFECTIVE_FROM = "1970-01-01";

/** A line's effectiveFrom with the legacy default applied. */
export function effectiveFromOf(line: BudgetTemplate): string {
  return line.effectiveFrom ?? OPEN_EFFECTIVE_FROM;
}

/** A line's effectiveTo with the legacy default (open-ended) applied. */
export function effectiveToOf(line: BudgetTemplate): string | null {
  return line.effectiveTo ?? null;
}

/** True when the line contributes to month M (its window touches the month). */
export function lineActiveInMonth(line: BudgetTemplate, month: Period): boolean {
  if (comparePeriods(periodOfDate(effectiveFromOf(line)), month) > 0) return false;
  const to = effectiveToOf(line);
  if (to !== null && comparePeriods(periodOfDate(to), month) < 0) return false;
  return true;
}

/** The real calendar length of month M (28/29/30/31; leap Februaries correct). */
export function daysInMonth(month: Period): number {
  return new Date(Date.UTC(month.year, month.month, 0)).getUTCDate();
}

/**
 * The number of days of month M covered by the line's effective window
 * [effectiveFrom, effectiveTo ?? open]. Clamps both ends to the month's bounds;
 * ISO YYYY-MM-DD strings compare correctly as strings, so this is pure string
 * arithmetic plus a day-of-month subtraction. Zero when the window misses M.
 */
export function activeDaysInMonth(line: BudgetTemplate, month: Period): number {
  const { first, last } = monthBounds(month);
  const from = effectiveFromOf(line);
  const to = effectiveToOf(line) ?? last;
  const start = from > first ? from : first;
  const end = to < last ? to : last;
  if (start > end) return 0;
  return Number(end.slice(8, 10)) - Number(start.slice(8, 10)) + 1;
}

/**
 * The line's day-weighted contribution to month M (owner decision, 2026-07-16):
 * round(amountCents * activeDays / daysInMonth), integer cents. Exactly
 * amountCents for full-month coverage; 0 when the window misses M.
 */
export function lineContributionForMonth(line: BudgetTemplate, month: Period): number {
  const active = activeDaysInMonth(line, month);
  if (active === 0) return 0;
  const total = daysInMonth(month);
  if (active === total) return line.amountCents;
  return Math.round((line.amountCents * active) / total);
}

/** The lines contributing to month M. */
export function linesForMonth(
  lines: readonly BudgetTemplate[],
  month: Period,
): BudgetTemplate[] {
  return lines.filter((l) => lineActiveInMonth(l, month));
}

/**
 * Month-resolved template: one summed amount per envelope for month M
 * (the versioned replacement for applyTemplate). Each line contributes its
 * DAY-WEIGHTED prorated amount; overlap within a month SUMS the prorations
 * (full-month overlaps still fully sum).
 */
export function resolveTemplateForMonth(
  lines: readonly BudgetTemplate[],
  month: Period,
): Map<string, number> {
  const out = new Map<string, number>();
  for (const line of linesForMonth(lines, month)) {
    out.set(line.envelopeId, (out.get(line.envelopeId) ?? 0) + lineContributionForMonth(line, month));
  }
  return out;
}

/** The summed (day-weighted) month-resolved amount for ONE envelope's lines in month M. */
export function resolveAmountForMonth(
  lines: readonly BudgetTemplate[],
  envelopeId: string,
  month: Period,
): number {
  let sum = 0;
  for (const line of lines) {
    if (line.envelopeId !== envelopeId) continue;
    sum += lineContributionForMonth(line, month);
  }
  return sum;
}

/**
 * The single line to adjust for an in-place delta edit (move-money /
 * distribute keep today's adjust-the-ongoing-plan semantics rather than
 * versioning every rebalance): the line contributing to `month` with the
 * greatest effectiveFrom, or null when none contributes.
 */
export function currentLineFor(
  lines: readonly BudgetTemplate[],
  envelopeId: string,
  month: Period,
): BudgetTemplate | null {
  let best: BudgetTemplate | null = null;
  for (const line of lines) {
    if (line.envelopeId !== envelopeId) continue;
    if (!lineActiveInMonth(line, month)) continue;
    if (best === null || effectiveFromOf(line) > effectiveFromOf(best)) best = line;
  }
  return best;
}

/**
 * Calendar day before an ISO date (pure calendar arithmetic; no timezone is
 * involved because both sides are already local calendar dates). Used by
 * completePrevious: the previous version ends the day before the new one starts.
 */
export function previousDay(isoDate: string): string {
  const d = new Date(`${isoDate}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() - 1);
  return d.toISOString().slice(0, 10);
}

/**
 * An income envelope's monthly budget for month M. Income budgets version
 * through the SAME effective-dated template lines (keyed by the income envelope
 * id). An income with no version lines at all falls back to the stored
 * `budgetedCents` (legacy back-compat: incomes budgets predate versioning);
 * once versions exist, resolution uses the SAME day-weighted proration the
 * expense resolvers use, so a mid-month income change prorates identically.
 */
export function resolveIncomeBudgetForMonth(
  lines: readonly BudgetTemplate[],
  income: IncomeEnvelope,
  month: Period,
): number {
  let hasLines = false;
  let sum = 0;
  for (const line of lines) {
    if (line.envelopeId !== income.id) continue;
    hasLines = true;
    sum += lineContributionForMonth(line, month);
  }
  return hasLines ? sum : income.budgetedCents;
}

/** Version status against the current (timezone-derived) month. */
export type VersionStatus = "completed" | "active" | "scheduled";

export function versionStatus(line: BudgetTemplate, now: Period): VersionStatus {
  if (comparePeriods(periodOfDate(effectiveFromOf(line)), now) > 0) return "scheduled";
  const to = effectiveToOf(line);
  if (to !== null && comparePeriods(periodOfDate(to), now) < 0) return "completed";
  return "active";
}

