147	export class PostgresStore implements BudgetStore {
148	  private readonly pool: Pool;
149	  /** Holds the dedicated client while a withTransaction is open on this async context. */
150	  private readonly txContext = new AsyncLocalStorage<PoolClient>();
151	
152	  constructor(connectionString: string) {
153	    this.pool = new Pool({ connectionString });
154	  }
155	
156	  /**
157	   * Every query in this adapter routes through here: inside a withTransaction
158	   * the dedicated transaction client is used (all statements of the transaction
159	   * MUST share one connection or BEGIN/COMMIT and the writes land on different
160	   * pool clients); outside one, the pool serves the query as before.
161	   */
162	  private q<R extends QueryResultRow = QueryResultRow>(
163	    sql: string,
164	    params?: readonly unknown[],
165	  ): Promise<QueryResult<R>> {
166	    const client = this.txContext.getStore();
167	    return (client ?? this.pool).query<R>(sql, params as unknown[]);
168	  }
169	
170	  /**
171	   * All-or-nothing transaction (see the Store port for the full semantics).
172	   * BEGIN/COMMIT/ROLLBACK on a dedicated pool client, carried on
173	   * AsyncLocalStorage so every this.q() inside `fn` hits the same connection
174	   * while unrelated concurrent queries keep using the pool. Nested calls join
175	   * the outer transaction (the outer commit/rollback decides); concurrent
176	   * top-level transactions each get their own client from the pool.
177	   */
178	  async withTransaction<T>(fn: () => Promise<T>): Promise<T> {
179	    if (this.txContext.getStore()) return fn(); // nested: join the outer transaction
180	
181	    const client = await this.pool.connect();
182	    try {
183	      await client.query("BEGIN");
184	      try {
185	        const out = await this.txContext.run(client, fn);
186	        await client.query("COMMIT");
187	        return out;
188	      } catch (err) {
189	        await client.query("ROLLBACK");
190	        throw err;
191	      }
192	    } finally {
193	      client.release();
194	    }
195	  }
196	
197	  async migrate(): Promise<void> {
198	    const client = await this.pool.connect();
199	    try {
200	      await client.query("BEGIN");
201	      for (const stmt of SCHEMA_SQL) await client.query(stmt);
202	      // Backfill additive columns on tables that predate them. Postgres supports
203	      // ADD COLUMN IF NOT EXISTS, so each is idempotent.
204	      for (const { table, column, ddl } of ADDITIVE_COLUMNS) {
205	        await client.query(`ALTER TABLE ${table} ADD COLUMN IF NOT EXISTS ${column} ${ddl}`);
206	      }
207	      // Collapse duplicate (user_id, envelope_id, period) allocation rows, then
208	      // enforce uniqueness (de-dup MUST precede the index). Logged, never silent.
209	      const dups = await client.query<{ user_id: string; envelope_id: string; period: string; n: string | number }>(
210	        ALLOCATIONS_DEDUP_FIND_SQL,
211	      );
212	      if (dups.rows.length > 0) {
213	        for (const d of dups.rows) {
214	          console.log(
215	            `[migrate] collapsing ${d.n} duplicate allocation rows for user=${d.user_id} envelope=${d.envelope_id} period=${d.period} (keeping lowest id, summing amounts)`,
216	          );
217	        }
218	        for (const stmt of ALLOCATIONS_DEDUP_SQL) await client.query(stmt);
219	      }
220	      await client.query(ALLOCATIONS_UNIQUE_INDEX_SQL);
221	      await client.query("COMMIT");
222	    } catch (err) {
223	      await client.query("ROLLBACK");
224	      throw err;
225	    } finally {
226	      client.release();
227	    }
228	  }
229	
230	  async ensureUser(userId: UserId, email?: string): Promise<void> {
231	    await this.q(
232	      `INSERT INTO users (id, email, created_at, status)
233	       VALUES ($1, $2, $3, 'active')
234	       ON CONFLICT (id) DO NOTHING`,
235	      [userId, email ?? `${userId}@penny.local`, Date.now()],
236	    );
237	  }
