149	export class PostgresStore implements BudgetStore {
150	  private readonly pool: Pool;
151	  /** Holds the dedicated client while a withTransaction is open on this async context. */
152	  private readonly txContext = new AsyncLocalStorage<PoolClient>();
153	
154	  constructor(connectionString: string) {
155	    this.pool = new Pool({ connectionString });
156	  }
157	
158	  /**
159	   * Every query in this adapter routes through here: inside a withTransaction
160	   * the dedicated transaction client is used (all statements of the transaction
161	   * MUST share one connection or BEGIN/COMMIT and the writes land on different
162	   * pool clients); outside one, the pool serves the query as before.
163	   */
164	  private q<R extends QueryResultRow = QueryResultRow>(
165	    sql: string,
166	    params?: readonly unknown[],
167	  ): Promise<QueryResult<R>> {
168	    const client = this.txContext.getStore();
169	    return (client ?? this.pool).query<R>(sql, params as unknown[]);
170	  }
171	
172	  /**
173	   * All-or-nothing transaction (see the Store port for the full semantics).
174	   * BEGIN/COMMIT/ROLLBACK on a dedicated pool client, carried on
175	   * AsyncLocalStorage so every this.q() inside `fn` hits the same connection
176	   * while unrelated concurrent queries keep using the pool. Nested calls join
177	   * the outer transaction (the outer commit/rollback decides); concurrent
178	   * top-level transactions each get their own client from the pool.
179	   */
180	  async withTransaction<T>(fn: () => Promise<T>): Promise<T> {
181	    if (this.txContext.getStore()) return fn(); // nested: join the outer transaction
182	
183	    const client = await this.pool.connect();
184	    try {
185	      await client.query("BEGIN");
186	      try {
187	        const out = await this.txContext.run(client, fn);
188	        await client.query("COMMIT");
189	        return out;
190	      } catch (err) {
191	        await client.query("ROLLBACK");
192	        throw err;
193	      }
194	    } finally {
195	      client.release();
196	    }
197	  }
198	
199	  async migrate(): Promise<void> {
200	    const client = await this.pool.connect();
201	    try {
202	      await client.query("BEGIN");
203	      for (const stmt of SCHEMA_SQL) await client.query(stmt);
204	      // Backfill additive columns on tables that predate them. Postgres supports
205	      // ADD COLUMN IF NOT EXISTS, so each is idempotent.
206	      for (const { table, column, ddl } of ADDITIVE_COLUMNS) {
207	        await client.query(`ALTER TABLE ${table} ADD COLUMN IF NOT EXISTS ${column} ${ddl}`);
208	      }
209	      // Collapse duplicate (user_id, envelope_id, period) allocation rows, then
210	      // enforce uniqueness (de-dup MUST precede the index). Logged, never silent.
211	      const dups = await client.query<{ user_id: string; envelope_id: string; period: string; n: string | number }>(
212	        ALLOCATIONS_DEDUP_FIND_SQL,
213	      );
214	      if (dups.rows.length > 0) {
215	        for (const d of dups.rows) {
216	          console.log(
217	            `[migrate] collapsing ${d.n} duplicate allocation rows for user=${d.user_id} envelope=${d.envelope_id} period=${d.period} (keeping lowest id, summing amounts)`,
218	          );
219	        }
220	        for (const stmt of ALLOCATIONS_DEDUP_SQL) await client.query(stmt);
221	      }
222	      await client.query(ALLOCATIONS_UNIQUE_INDEX_SQL);
223	      // Garbage-era purge (see schema.ts). Logged, idempotent.
224	      const garbage = await client.query<{ n: string | number }>(GARBAGE_ALLOCATIONS_COUNT_SQL);
225	      if (Number(garbage.rows[0]?.n ?? 0) > 0) {
226	        console.log(`[migrate] purging ${garbage.rows[0]!.n} out-of-era allocation rows (garbage-date materialisation)`);
227	        for (const stmt of GARBAGE_PURGE_SQL) await client.query(stmt);
228	      }
229	      await client.query("COMMIT");
230	    } catch (err) {
231	      await client.query("ROLLBACK");
232	      throw err;
233	    } finally {
234	      client.release();
235	    }
236	  }
237	
238	  async ensureUser(userId: UserId, email?: string): Promise<void> {
239	    await this.q(
240	      `INSERT INTO users (id, email, created_at, status)
241	       VALUES ($1, $2, $3, 'active')
242	       ON CONFLICT (id) DO NOTHING`,
243	      [userId, email ?? `${userId}@penny.local`, Date.now()],
244	    );
245	  }
