169	function orderEnvelopes(envelopes: readonly StoreEnvelope[]): StoreEnvelope[] {
170	  const byParent = new Map<string | null, StoreEnvelope[]>();
171	  for (const e of envelopes) {
172	    const arr = byParent.get(e.parentId) ?? [];
173	    arr.push(e);
174	    byParent.set(e.parentId, arr);
175	  }
176	  for (const arr of byParent.values()) arr.sort((a, b) => a.name.localeCompare(b.name));
