/**
 * Behaviour of the newly-registered routes (previously declared in the
 * contract but never routed): POST /api/move (alias of /api/envelopes/move),
 * POST /api/envelopes/edit, and GET /api/movements. Driven through the real
 * app over the in-memory store, signed in, exactly as the SPA calls them.
 */

import { describe, test, expect } from "bun:test";
import type { GridResponse, MoveMoneyResponse, CreateEnvelopeResponse, EditEnvelopeResponse, MovementsResponse, BudgetHistoryResponse } from "../src/server/contract.ts";
import { makeTestApp, postJson, getJson, LOCAL_USER_ID, type TestApp } from "./server-test-app.ts";

async function createEnvelope(t: TestApp, cookie: string, body: unknown): Promise<string> {
  const res = await postJson(t.app, "/api/envelopes", body, cookie);
  expect(res.status).toBe(200);
  const created = (await res.json()) as CreateEnvelopeResponse;
  return created.id;
}

async function grid(t: TestApp, cookie: string): Promise<GridResponse> {
  const res = await getJson(t.app, "/api/envelopes", cookie);
  expect(res.status).toBe(200);
  return (await res.json()) as GridResponse;
}

describe("POST /api/move (the MoveMoneyModal endpoint)", () => {
  test("moves conserved money exactly like /api/envelopes/move", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    const groceries = await createEnvelope(t, cookie, { name: "Groceries", type: "expense", budgetedCents: 40000, period: "monthly" });
    const fun = await createEnvelope(t, cookie, { name: "Fun", type: "expense", budgetedCents: 20000, period: "monthly" });

    // Note: the month was opened by the FIRST create's ensureMonth, so Fun's
    // template line does not materialise into the current month (existing
    // engine semantics) — Fun starts this month at left 0.
    const res = await postJson(t.app, "/api/move", { fromEnvelopeId: groceries, toEnvelopeId: fun, amountCents: 5000, scope: "this_month" }, cookie);
    expect(res.status).toBe(200);
    const moved = (await res.json()) as MoveMoneyResponse;
    expect(moved.ok).toBe(true);
    expect(moved.fromLeftCents).toBe(35000);
    expect(moved.toLeftCents).toBe(5000);

    // The alias hits the same engine: a second move via the original path
    // continues from the alias's result (conservation across both routes).
    const res2 = await postJson(t.app, "/api/envelopes/move", { fromEnvelopeId: fun, toEnvelopeId: groceries, amountCents: 5000, scope: "this_month" }, cookie);
    expect(res2.status).toBe(200);

