1	/**
2	 * Envelope route handlers: the Dave Ramsey grid with four-figure rollups, the
3	 * time-travel as-of grid, per-envelope detail, and conserved move-money. Every
4	 * route is scoped to the authenticated user (ISC-49) and reads/writes through
5	 * the real envelope and budget engines. Every mutation body is validated with
6	 * zod at the boundary (see ../validate.ts) before it can reach the ledger.
7	 *
8	 * The grid first ensures the current month has its budget (auto-roll, ISC-29 /
9	 * ISC-76) so a freshly opened month is never blank without any manual step.
10	 */
11	
12	import { Hono } from "hono";
13	import type { Context } from "hono";
14	import type { Container } from "../../composition.ts";
15	import type { Services } from "../services.ts";
16	import type { ApiError, MoveMoneyResponse, DistributeResponse, CreateEnvelopeResponse, SetCarryoverResponse, ArchiveEnvelopeResponse, ArchivedEnvelopesResponse, SetRolloverResponse, EditEnvelopeResponse, MovementsResponse, MovementView, CarryoverHistoryResponse } from "../contract.ts";
17	import type { BudgetPeriod } from "../../domain/types.ts";
18	import { currentPeriod, resolveSession, UNAUTHENTICATED } from "../http.ts";
