describe("income start dates follow REAL history (2026-08-12)", () => {
  test("the synthetic chronology row and the first-edit baseline start at the earliest mapped inflow, not the import anchor", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    const id = await createEnvelope(t, cookie, { name: "Salary", type: "income", parentId: null, budgetedCents: 500000, targetCents: 500000 });
    // Import anchor says 2026-06-01, but the mapped inflow history begins 2023-07.
    await t.store.setIncomeCarryover(LOCAL_USER_ID, id, 0, "2026-06-01");
    await t.store.upsertMapping(LOCAL_USER_ID, {
      id: "map-sal", userId: LOCAL_USER_ID, categoryId: "cat-sal", envelopeId: id,
      effectiveFrom: "1970-01-01", effectiveTo: null,
    });
    await t.store.upsertTransactions(LOCAL_USER_ID, [{
      id: "pay1", date: "2023-07-14", amountCents: 500000, accountId: "a", categoryId: "cat-sal",
      envelopeId: null, payee: "Employer", isTransfer: false, isPending: false, rawJson: "{}",
    }]);

    // Synthetic row (no stored versions yet) shows the real history start.
    const synth = await getJson(t.app, `/api/envelopes/versions?envelopeId=${id}`, cookie);
    const synthBody = (await synth.json()) as BudgetVersionsResponse;
    expect(synthBody.versions[0]?.effectiveFrom).toBe("2023-07-01");

    // First edit bootstraps the baseline at the same real start.
    await postJson(t.app, "/api/envelopes/edit", { id, type: "income", budgetedCents: 600000, targetCents: 600000 }, cookie);
    const after = (await (await getJson(t.app, `/api/envelopes/versions?envelopeId=${id}`, cookie)).json()) as BudgetVersionsResponse;
    const baseline = after.versions.find((v) => v.amountCents === 500000);
    expect(baseline?.effectiveFrom).toBe("2023-07-01");
  });
});
