/** Era reconstruction + history merge (PocketSmith backfill, 2026-08-12). */
import { describe, test, expect } from "bun:test";
import { erasFromMonthly, planHistoryMerge } from "../src/ingest/budget-history.ts";

describe("erasFromMonthly", () => {
  test("collapses equal consecutive months; zero months become gaps", () => {
    const eras = erasFromMonthly([
      { month: "2023-07-01", amountCents: 500000 },
      { month: "2023-08-01", amountCents: 500000 },
      { month: "2023-09-01", amountCents: 0 },
      { month: "2023-10-01", amountCents: 550000 },
      { month: "2023-11-01", amountCents: 550000 },
    ]);
    expect(eras).toEqual([
      { from: "2023-07-01", to: "2023-08-31", amountCents: 500000 },
      { from: "2023-10-01", to: "2023-11-30", amountCents: 550000 },
    ]);
  });
});

describe("planHistoryMerge", () => {
  test("clips at the takeover, extends the current budget back on same-amount adjacency (the 1/1/25 salary case)", () => {
    const eras = erasFromMonthly([
      { month: "2024-11-01", amountCents: 700000 },
      { month: "2024-12-01", amountCents: 700000 },
      { month: "2025-01-01", amountCents: 750000 },
      { month: "2025-02-01", amountCents: 750000 },
      // ... continues at 750000 to the takeover
      { month: "2026-04-01", amountCents: 750000 },
      { month: "2026-05-01", amountCents: 750000 },
    ]);
    const plan = planHistoryMerge("inc-salary", eras, "2026-06-01", 750000);
    // The 750000 era adjoins the takeover with the same amount → EXTEND, so the
    // current budget reads "from 2025-01-01 — ongoing".
    expect(plan.extendTakeoverTo).toBe("2025-01-01");
    // The earlier 700000 era imports as a closed historical version.
    expect(plan.inserts).toEqual([
      { envelopeId: "inc-salary", amountCents: 700000, period: "monthly", effectiveFrom: "2024-11-01", effectiveTo: "2024-12-31" },
    ]);
  });

  test("a different adjacent amount imports as its own closed era (no extension)", () => {
    const eras = erasFromMonthly([{ month: "2026-05-01", amountCents: 111100 }]);
    const plan = planHistoryMerge("env-x", eras, "2026-06-01", 999900);
    expect(plan.extendTakeoverTo).toBeNull();
    expect(plan.inserts[0]).toMatchObject({ effectiveFrom: "2026-05-01", effectiveTo: "2026-05-31", amountCents: 111100 });
  });

  test("eras inside BudgetBuddy-owned history are dropped; straddlers are clipped", () => {
    const eras = erasFromMonthly([
      { month: "2026-05-01", amountCents: 100000 },
      { month: "2026-06-01", amountCents: 100000 },
      { month: "2026-07-01", amountCents: 100000 },
    ]);
    const plan = planHistoryMerge("env-x", eras, "2026-06-01", 55500);
    expect(plan.inserts).toEqual([
      { envelopeId: "env-x", amountCents: 100000, period: "monthly", effectiveFrom: "2026-05-01", effectiveTo: "2026-05-31" },
    ]);
  });
});
