1	/**
2	 * One-off budget-history backfill from PocketSmith (owner request 2026-08-12).
3	 *
4	 *   bun run scripts/backfill-budget-history.ts            # dry-run (report only)
5	 *   bun run scripts/backfill-budget-history.ts --apply    # write (after a DB backup)
6	 *
7	 * For every mapped category, pulls the REAL monthly budget series from
8	 * PocketSmith trend analysis (forecast_amount = its budget events), collapses
9	 * it into eras, and imports the eras UNDER the existing BudgetBuddy chronology:
10	 * history before the envelope's takeover (its anchor date, capped by its
11	 * earliest hand-authored version) is filled; BudgetBuddy-authored budgets are
12	 * never modified — except extending the takeover line BACK when the adjacent
13	 * era carries the same amount ("current budget since 1/1/25"). Historical
14	 * materialised months are then recomputed from the final chronology (D4).
15	 */
16	
17	import { copyFileSync, existsSync } from "node:fs";
18	import { buildContainer } from "../src/composition.ts";
19	import { installSecretLogRedaction } from "../src/server/redaction.ts";
20	import { PocketSmithClient } from "../src/ingest/client.ts";
21	import { erasFromMonthly, planHistoryMerge, type MonthBudget } from "../src/ingest/budget-history.ts";
22	import { effectiveFromOf, effectiveToOf, resolveTemplateForMonth } from "../src/budget/versions.ts";
23	import { findOverlaps, isTombstone } from "../src/budget/window.ts";
24	import type { BudgetTemplate } from "../src/domain/types.ts";
25	import type { EnvelopeStore } from "../src/envelope/ports.ts";
26	import type { BudgetStore } from "../src/budget/ports.ts";
27	
28	const APPLY = process.argv.includes("--apply");
29	const userId = process.env.PENNY_USER_ID ?? "local";
30	const DEFAULT_TAKEOVER = "2026-06-01"; // the BudgetBuddy import month
31	
32	const container = await buildContainer();
33	const { secrets } = installSecretLogRedaction(container.secrets);
34	const store = container.store as BudgetStore & EnvelopeStore;
35	
36	if (APPLY) {
37	  const dbPath = process.env.PENNY_SQLITE_PATH ?? `${process.env.HOME}/.penny/penny.db`;
38	  if (existsSync(dbPath)) {
39	    const backup = dbPath.replace(/\.db$/, `.pre-history-backfill.db`);
40	    copyFileSync(dbPath, backup);
41	    if (existsSync(`${dbPath}-wal`)) copyFileSync(`${dbPath}-wal`, `${backup}-wal`);
42	    console.log(`[backfill] backup written: ${backup}`);
43	  }
44	}
45	
46	const client = await PocketSmithClient.forUser(secrets, userId);
47	const user = await client.getAuthenticatedUser();
48	if (user.id === undefined || user.id === null) throw new Error("PocketSmith returned no user id.");
49	
50	// Scenario ids (trend analysis requires them) from the accounts surface.
51	const accounts = await client.listAccounts(user.id);
52	const scenarioIds = [
53	  ...new Set(
54	    accounts.flatMap((a) => [
55	      ...(a.scenarios?.map((sc) => sc.id) ?? []),
56	      a.primary_scenario?.id,
57	    ]).filter((x): x is number => typeof x === "number"),
58	  ),
59	];
60	if (scenarioIds.length === 0) throw new Error("No PocketSmith scenarios found.");
61	
62	const [mappings, template, incomes, txs] = await Promise.all([
63	  store.listMappings(userId),
64	  store.listTemplate(userId),
65	  store.listIncomeEnvelopes(userId),
66	  store.listTransactions(userId),
67	]);
68	const incomeIds = new Set(incomes.map((i) => i.id));
69	const catToEnv = new Map(mappings.map((m) => [m.categoryId, m.envelopeId]));
70	const categoryIds = [...catToEnv.keys()];
71	
72	const firstTxMonth = txs.reduce<string | null>((min, t) => (min === null || t.date < min ? t.date : min), null)?.slice(0, 7);
73	if (!firstTxMonth) throw new Error("No transactions — nothing to backfill against.");
74	const startDate = `${firstTxMonth}-01`;
75	const endDate = new Date().toISOString().slice(0, 10);
76	
77	console.log(`[backfill] trend analysis ${startDate}..${endDate} for ${categoryIds.length} categories, ${scenarioIds.length} scenarios`);
78	
79	const toCents = (amount: number | undefined): number =>
80	  amount === undefined || Number.isNaN(amount) ? 0 : Math.abs(Math.round(amount * 100));
81	
82	let insertedTotal = 0;
83	let extendedTotal = 0;
84	for (const catId of categoryIds) {
85	  const envelopeId = catToEnv.get(catId);
86	  if (envelopeId === undefined) continue;
87	  const isIncome = incomeIds.has(envelopeId);
88	  // One call per category: the single-category response is a plain
89	  // {income, expense} package. Throttled to stay friendly to the API.
90	  const pkg = await client.trendAnalysis(user.id, { category: catId, scenarios: scenarioIds, startDate, endDate });
91	  await new Promise((r) => setTimeout(r, 150));
92	  const analysis = isIncome ? pkg.income : pkg.expense;
93	  const periods = analysis?.periods ?? [];
94	  const series: MonthBudget[] = periods
95	    .filter((p) => p.start_date !== undefined)
96	    .map((p) => ({ month: p.start_date!, amountCents: toCents(p.forecast_amount) }));
97	  const eras = erasFromMonthly(series);
98	  if (eras.length === 0) continue;
99	
100	  // The takeover: the envelope's earliest live BudgetBuddy line (its start is
101	  // where BudgetBuddy's own chronology begins), else the import default.
102	  const live = template.filter((l) => l.envelopeId === envelopeId && !isTombstone(l));
103	  const earliest = live.sort((a, b) => effectiveFromOf(a).localeCompare(effectiveFromOf(b)))[0];
104	  // For incomes with no lines yet the whole PS chronology stands alone (the
105	  // last era stays open-ended by taking over at "9999" and nothing to extend).
106	  const takeoverFrom = earliest ? effectiveFromOf(earliest) : DEFAULT_TAKEOVER;
107	  const takeoverAmount = earliest?.amountCents ?? -1;
108	
109	  const plan = planHistoryMerge(envelopeId, eras, takeoverFrom, takeoverAmount);
110	  if (plan.inserts.length === 0 && plan.extendTakeoverTo === null) continue;
111	
112	  const name = pkg.category?.title ?? envelopeId;
113	  console.log(`\n${name} (${envelopeId})${isIncome ? " [income]" : ""} — takeover ${takeoverFrom}:`);
114	  for (const line of plan.report) console.log(line);
115	
116	  if (!APPLY) continue;
117	
118	  await store.withTransaction(async () => {
119	    const working: BudgetTemplate[] = (await store.listTemplate(userId)).filter((l) => l.envelopeId === envelopeId);
120	    for (const ins of plan.inserts) {
121	      const line: BudgetTemplate = { ...ins, id: crypto.randomUUID(), userId };
122	      await store.putTemplateLine(userId, line);
123	      working.push(line);
124	      insertedTotal++;
125	    }
126	    if (plan.extendTakeoverTo !== null && earliest) {
127	      const extended: BudgetTemplate = {
128	        ...earliest,
129	        effectiveFrom: plan.extendTakeoverTo,
130	        effectiveTo: effectiveToOf(earliest),
131	      };
132	      await store.putTemplateLine(userId, extended);
133	      const idx = working.findIndex((l) => l.id === earliest.id);
134	      if (idx >= 0) working[idx] = extended;
135	      extendedTotal++;
136	    }
137	    const overlaps = findOverlaps(working.filter((l) => !isTombstone(l)));
138	    if (overlaps.length > 0) throw new Error(`overlap after merge for ${envelopeId} — aborted`);
139	
140	    // D4: recompute the envelope's materialised months from the final lines
141	    // (income envelopes resolve live and materialise nothing).
142	    if (!isIncome) {
143	      const months = await store.listAllocationPeriods(userId);
144	      for (const key of months) {
145	        if (key < "1990-01" || key > "2100-12") continue;
146	        const m = { year: Number(key.slice(0, 4)), month: Number(key.slice(5, 7)) };
147	        const allocs = await store.listAllocations(userId, key);
148	        if (allocs.length === 0) continue;
149	        const mine = allocs.find((a) => a.envelopeId === envelopeId);
150	        if (mine?.scope === "this_month") continue;
151	        const resolved = resolveTemplateForMonth(working, m).get(envelopeId) ?? 0;
152	        if ((mine?.amountCents ?? 0) === resolved) continue;
153	        await store.putAllocation(userId, {
154	          id: mine?.id ?? crypto.randomUUID(),
155	          envelopeId,
156	          period: key,

