p='src/ingest/client.ts'; s=open(p).read()
old="""  /**
   * Page through a user's transactions to completion (ISC-4)."""
new="""  /**
   * List a user's calendar events (the budget event series occurrences) over a
   * date window, following Link-header pagination to completion. GET-only;
   * feeds the budget-history backfill (series_id groups an era's occurrences).
   */
  async listEvents(
    pocketsmithUserId: number,
    startDate: string,
    endDate: string,
  ): Promise<
    {
      id?: string;
      category?: { id?: number; title?: string };
      amount?: number;
      date?: string;
      repeat_type?: string;
      repeat_interval?: number;
      series_id?: number;
      infinite_series?: boolean;
    }[]
  > {
    type Ev = Awaited<ReturnType<PocketSmithClient["listEvents"]>>[number];
    const out: Ev[] = [];
    let url: string | null = (() => {
      const u = new URL(`${this.baseUrl}/users/${pocketsmithUserId}/events`);
      u.searchParams.set("start_date", startDate);
      u.searchParams.set("end_date", endDate);
      u.searchParams.set("per_page", String(this.perPage));
      return u.toString();
    })();
    while (url !== null) {
      const res = await this.get(url);
      out.push(...((await res.json()) as Ev[]));
      url = nextLink(res.headers.get("link"));
    }
    return out;
  }

  /**
   * Page through a user's transactions to completion (ISC-4)."""
