  test("a fortnightly salary series is ONE steady era at its monthly equivalent, and rate changes split eras", async () => {
    const { erasFromSeries } = await import("../src/ingest/budget-history.ts");
    const evs = [];
    // Series 1: $2,937.05/fortnight Jul-Sep 2023.
    for (const d of ["2023-07-06", "2023-07-20", "2023-08-03", "2023-08-17", "2023-08-31", "2023-09-14", "2023-09-28"])
      evs.push({ seriesId: 1, date: d, amountCents: 293705, repeatType: "fortnightly", repeatInterval: 1 });
    // Series 2: new rate from October.
    for (const d of ["2023-10-12", "2023-10-26", "2023-11-09"])
      evs.push({ seriesId: 2, date: d, amountCents: 289348, repeatType: "fortnightly", repeatInterval: 1 });
    const eras = erasFromSeries(evs);
    expect(eras).toHaveLength(2);
    expect(eras[0]).toMatchObject({ from: "2023-07-01", to: "2023-09-30", amountCents: Math.round((293705 * 26) / 12), periodLabel: "fortnightly" });
    expect(eras[1]?.from).toBe("2023-10-01");
  });
});
