private toRows(
  envelopes: readonly StoreEnvelope[],
  rolled: ReadonlyMap<string, RolledFigures>,
  templatePeriods: ReadonlyMap<string, BudgetPeriod>,
  rolloverStartById: ReadonlyMap<string, string | null>,
  ownAllocation: ReadonlyMap<string, number>,
  ownCarryover: ReadonlyMap<string, number>,
): EnvelopeRow[] {
  // Live (non-tombstone) version windows per envelope intersecting the
  // rendered range: the source of the DERIVED active flag.
  const rangeFirst = monthBounds(range.from).first;
  const rangeLast = monthBounds(target).last;
  const activeByEnvelope = new Map<string, boolean>();
  for (const l of template) {
    const to = l.effectiveTo ?? null;
    const from = l.effectiveFrom ?? "1970-01-01";
    if (to !== null && to < from) continue; // tombstone
    if (from <= rangeLast && (to === null || to >= rangeFirst)) {
      activeByEnvelope.set(l.envelopeId, true);
    }
  }

  return orderEnvelopes(envelopes).map((e) => {
    const r = rolled.get(e.id);
    return {
      id: e.id,
      parentId: e.parentId,
      name: e.name,
      group: e.group,
      rolloverRule: normaliseRolloverRule(e.rolloverRule),
      targetType: e.targetType,
      targetAmountCents: e.targetAmountCents,
      type: e.type ?? "expense",
      // DERIVED (owner decision 2026-08-12): a budget is active when a live
      // version window intersects the rendered range — the dates decide, not
      // a manual toggle. Envelopes with no budget lines read inactive (no
      // budget in force); their spend still renders and totals are unaffected.
      active: activeByEnvelope.get(e.id) ?? false,
      archived: e.archived ?? false,
      period: templatePeriods.get(e.id) ?? "monthly",
      rolloverStart: rolloverStartById.get(e.id) ?? null,
      carryoverCents: r?.carryoverCents ?? 0,
      ownCarryoverCents: ownCarryover.get(e.id) ?? 0,
      allocationCents: r?.allocationCents ?? 0,
      ownAllocationCents: ownAllocation.get(e.id) ?? 0,
      totalCents: r?.totalCents ?? 0,
      leftCents: r?.leftCents ?? 0,
      depth: r?.depth ?? 0,
    };
  });

