49	const OCCURRENCES_PER_YEAR: Record<string, number> = {
50	  daily: 365,
51	  weekly: 52,
52	  fortnightly: 26,
53	  monthly: 12,
54	  yearly: 1,
55	};
56	
57	const PERIOD_LABEL: Record<string, BudgetEra["periodLabel"]> = {
58	  weekly: "weekly",
59	  fortnightly: "fortnightly",
60	  monthly: "monthly",
61	  yearly: "annual",
