64	/**
65	 * Reconstruct budget eras from a category's event SERIES: each series is one
66	 * budget definition (rate + cadence) whose era runs from its first occurrence's
67	 * month to its last occurrence's month. The era amount is the series' rate
68	 * normalised to a monthly equivalent (rate × occurrences-per-year ÷ 12) — the
69	 * app's cadence convention — so a fortnightly salary is one steady era, not a
70	 * month-by-month smear of pay-cycle counts. Overlapping series in one category
71	 * (concurrent budget lines) make faithful non-overlapping windows impossible;
72	 * the caller detects that via findEraOverlap and skips with a warning.
73	 */
74	export function erasFromSeries(events: readonly SeriesEvent[]): BudgetEra[] {
75	  const bySeries = new Map<number, SeriesEvent[]>();
76	  for (const e of events) {
77	    if (!(e.repeatType in OCCURRENCES_PER_YEAR) && e.repeatType !== "once") continue;
78	    const arr = bySeries.get(e.seriesId) ?? [];
79	    arr.push(e);
80	    bySeries.set(e.seriesId, arr);
81	  }
82	  const eras: BudgetEra[] = [];
83	  for (const arr of bySeries.values()) {
84	    arr.sort((a, b) => a.date.localeCompare(b.date));
85	    const first = arr[0]!;
86	    if (first.repeatType === "once") continue; // one-offs are not budgets
87	    const last = arr[arr.length - 1]!;
88	    const perYear = OCCURRENCES_PER_YEAR[first.repeatType]! / Math.max(1, first.repeatInterval);
89	    const monthly = Math.round((first.amountCents * perYear) / 12);
90	    if (monthly === 0) continue;
91	    eras.push({
92	      from: `${first.date.slice(0, 7)}-01`,
93	      to: lastDayOfMonth(`${last.date.slice(0, 7)}-01`),
94	      amountCents: monthly,
95	      periodLabel: PERIOD_LABEL[first.repeatType] ?? "monthly",
96	    });
97	  }
98	  eras.sort((a, b) => a.from.localeCompare(b.from));
99	  // Adjacent eras from rate changes may share a boundary month (old series
100	  // ends mid-month, new begins mid-month): clip the earlier era to end the
101	  // month BEFORE the later one starts, keeping windows disjoint.
102	  for (let i = 0; i < eras.length - 1; i++) {
103	    const cur = eras[i]!, next = eras[i + 1]!;
104	    if (cur.to >= next.from) {
105	      const clippedTo = previousDay(next.from);
106	      if (clippedTo < cur.from) continue; // fully swallowed: flagged as overlap below
107	      eras[i] = { ...cur, to: clippedTo };
108	    }
109	  }
110	  return eras;
111	}
