113	/** True when any two eras still overlap (concurrent budget series). */
114	export function findEraOverlap(eras: readonly BudgetEra[]): boolean {
115	  for (let i = 0; i < eras.length; i++) {
116	    for (let j = i + 1; j < eras.length; j++) {
117	      if (eras[i]!.from <= eras[j]!.to && eras[j]!.from <= eras[i]!.to) return true;
118	    }
119	  }
120	  return false;
121	}
