123	/** Last day of the month containing the given first-day date. */
124	export function lastDayOfMonth(firstDay: string): string {
125	  const y = Number(firstDay.slice(0, 4));
126	  const m = Number(firstDay.slice(5, 7));
127	  const last = new Date(Date.UTC(y, m, 0)).getUTCDate();
128	  return `${firstDay.slice(0, 8)}${String(last).padStart(2, "0")}`;
129	}
