57	  { type: "expense", title: "Expenses", icon: Receipt },
58	  { type: "envelope", title: "Envelopes", icon: Mail },
59	];
60	
61	/**
62	 * The figure the wizard edits: the row's OWN allocation, never the rolled-up
63	 * descendant total. For a leaf own == rolled, so the fallback (older payloads
64	 * without the field) is exact there; for a parent the own line is the only
65	 * editable figure.
66	 */
67	const ownAlloc = (r: EnvelopeRow): number => r.ownAllocationCents ?? r.allocationCents;
