1	/**
2	 * New-category detection + adopt routes. A synced transaction can carry a
3	 * PocketSmith category that has no envelope mapping yet (distinct from an
4	 * uncategorised transaction, which has NO category at all): these routes list
5	 * those categories and let the user adopt each into the budget.
6	 *
7	 *   GET  /api/categories/unmapped  distinct unmapped categories with aggregates
8	 *   POST /api/categories/adopt     create envelope + mapping in one transaction
9	 *
10	 * Every route is scoped to the authenticated user (ISC-49); the adopt body is
11	 * validated with zod at the boundary (../validate.ts) before it reaches the
12	 * ledger, and the multi-write adopt runs inside one store transaction.
13	 */
14	
15	import { Hono } from "hono";
16	import type { Container } from "../../composition.ts";
17	import type { Services } from "../services.ts";
18	import type {
19	  AdoptCategoryResponse,
20	  DismissCategoryResponse,
21	  DismissedCategoriesResponse,
22	  UnmappedCategoriesResponse,
23	} from "../contract.ts";
24	import { currentPeriod, resolveSession, UNAUTHENTICATED } from "../http.ts";
25	import { todayISO } from "../../platform/time.ts";
26	import { parseBody, adoptCategorySchema, dismissCategorySchema, dateParam, dateParamResponse } from "../validate.ts";
27	
28	export function registerCategories(api: Hono, container: Container, services: Services): void {
29	  const tz = container.config.timezone;
30	
31	  // Distinct categories present on transactions but not in the budget, most
32	  // transactions first. Optional from/to (YYYY-MM-DD) scope the scan; read raw
33	  // from the query to match the neighbouring grid handler's from/to handling.
34	  api.get("/categories/unmapped", async (c) => {
35	    const session = await resolveSession(c, container);
36	    if (!session) return c.json(UNAUTHENTICATED, 401);
37	    let from: string | undefined, to: string | undefined;
38	    try {
39	      from = dateParam("from", c.req.query("from"));
40	      to = dateParam("to", c.req.query("to"));
41	    } catch (err) {
42	      return dateParamResponse(c, err);
43	    }
44	    const categories = await services.envelopes.listUnmappedCategories(session.userId, {
45	      ...(from ? { from } : {}),
46	      ...(to ? { to } : {}),
47	      tz,
48	    });
49	    const res: UnmappedCategoriesResponse = { categories };
50	    return c.json(res);
51	  });
52	
53	  // The cleared categories (Settings → Not synced): same aggregates as the
54	  // unmapped list, restricted to dismissed ids.
55	  api.get("/categories/dismissed", async (c) => {
56	    const session = await resolveSession(c, container);
57	    if (!session) return c.json(UNAUTHENTICATED, 401);
58	    const categories = await services.envelopes.listDismissedCategories(session.userId, tz);
59	    const res: DismissedCategoriesResponse = { categories };
60	    return c.json(res);
61	  });
62	
63	  // Clear (dismiss) or restore one detected category. Dismissed categories
64	  // stop appearing on the budget page and list under Settings → Not synced.
65	  api.post("/categories/dismiss", async (c) => {
66	    const session = await resolveSession(c, container);
67	    if (!session) return c.json(UNAUTHENTICATED, 401);
68	    const parsed = await parseBody(c, dismissCategorySchema);
69	    if (!parsed.ok) return parsed.response;
70	    await services.envelopes.setCategoryDismissed(session.userId, parsed.value.categoryId, parsed.value.dismissed);
71	    const res: DismissCategoryResponse = { ok: true };
72	    return c.json(res);
73	  });
74	
75	  // Adopt one category: create the envelope and seed the category→envelope
76	  // mapping in a single store transaction (BudgetService.adoptCategory). The
77	  // handler only resolves the timezone-dependent schedule anchor default.
78	  api.post("/categories/adopt", async (c) => {
79	    const session = await resolveSession(c, container);
80	    if (!session) return c.json(UNAUTHENTICATED, 401);
81	    const parsed = await parseBody(c, adoptCategorySchema);
82	    if (!parsed.ok) return parsed.response;
83	    const req = parsed.value;
84	    const envelopeId = await services.budget.adoptCategory(session.userId, currentPeriod(tz), {
85	      categoryId: req.categoryId,
86	      name: req.name,
87	      type: req.type,
88	      // The rollover sequence anchors where the budget starts: the client's
89	      // chosen start date when given, else today (the pre-start-date default).
90	      rolloverStart: req.effectiveFrom ?? todayISO(tz),
91	      ...(req.budgetedCents !== undefined ? { budgetedCents: req.budgetedCents } : {}),
92	      ...(req.period !== undefined ? { period: req.period } : {}),
93	      ...(req.rolloverRule !== undefined ? { rolloverRule: req.rolloverRule } : {}),
94	      ...(req.parentId !== undefined ? { parentId: req.parentId } : {}),
95	      ...(req.effectiveFrom !== undefined ? { effectiveFrom: req.effectiveFrom } : {}),
96	      ...(req.existingEnvelopeId !== undefined ? { existingEnvelopeId: req.existingEnvelopeId } : {}),
97	    });
98	    const res: AdoptCategoryResponse = { envelopeId };
99	    return c.json(res);
100	  });
101	}

1	/**
2	 * The typed API contract. This is the single source of truth for the wire shapes
3	 * exchanged between the SPA and the Hono handlers. Locking it here lets the UI and
4	 * the handler implementations be built in parallel against the same types.
5	 *
6	 * Conventions:
7	 *   - All money is integer cents (field names end in Cents).
8	 *   - Dates are ISO strings (YYYY-MM-DD); timestamps are epoch millis (asOf, ts).
9	 *   - Every response that reflects tenant state is implicitly scoped to the
10	 *     authenticated user_id resolved by the AuthProvider; user_id is never a
11	 *     request field (the session carries it).
12	 */
