import * as React from "react";
import { Wallet, TrendingUp, PiggyBank, Mail, Plus } from "lucide-react";
import type { EnvelopeRow, UnmappedCategory } from "@contract";
import type { EnvelopeType, BudgetPeriod } from "@domain";
import { call, isApiError, ApiCallError } from "@/lib/api";
import { useInvalidateAfterAdopt } from "@/lib/queries";
import {
  cn,
  formatCents,
  normalisePeriods,
  firstOfCurrentMonthIso,
  BUDGET_PERIODS,
  BUDGET_PERIOD_LABELS,
} from "@/lib/utils";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from "@/components/ui/select";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** The unmapped category being adopted (null closes the modal). */
  category: UnmappedCategory | null;
  /** Existing envelopes the new one can sit under (expense parent candidates). */
  rows: readonly EnvelopeRow[];
  /** Income envelopes, offered as map-to-existing targets alongside the rows. */
  incomes?: readonly { id: string; name: string }[];
}

const TYPE_OPTIONS: readonly { value: EnvelopeType; label: string; icon: typeof Wallet }[] = [
  { value: "income", label: "Income", icon: TrendingUp },
  { value: "expense", label: "Expense", icon: Wallet },
  { value: "saving", label: "Saving", icon: PiggyBank },
  { value: "envelope", label: "Envelope", icon: Mail },
];

/**
 * Infer the default envelope type for a category: a net-positive total reads as
 * income (money coming in), otherwise an expense. This is the "mostly positive
 * amounts → income" rule, proxied through the signed total the endpoint returns.
 */
export function inferDefaultType(category: UnmappedCategory): EnvelopeType {
  return category.totalCents > 0 ? "income" : "expense";
}

/**
 * Adopt-category wizard. Turns one detected PocketSmith category into a budget
 * envelope plus a category→envelope mapping (POST /api/categories/adopt). Reuses
 * AddBudgetModal's field idiom: the name pre-fills from the category, the type
 * defaults from the transactions' direction (net-positive → income), and the
 * user sets the type, a budget amount + cadence, and an optional parent. On
 * success the budget, unmapped-category, and transaction queries all invalidate.
 */
export function AdoptCategoryModal({ open, onOpenChange, category, rows, incomes = [] }: Props) {
  const invalidateAfterAdopt = useInvalidateAfterAdopt();

  const [type, setType] = React.useState<EnvelopeType>("expense");
  // Map to an EXISTING category instead of creating one (owner request
  // 2026-08-12): only the category→envelope mapping is written.
  const [existingId, setExistingId] = React.useState<string>("__new__");
  const [name, setName] = React.useState("");
  const [parentId, setParentId] = React.useState<string>("__top__");
  const [price, setPrice] = React.useState("");
  const [period, setPeriod] = React.useState<BudgetPeriod>("monthly");
  // Start date for the budget line AND the category→envelope mapping (and the
  // rollover anchor server-side). Defaults to the first of the current month.
  const [effectiveFrom, setEffectiveFrom] = React.useState<string>(firstOfCurrentMonthIso());
  const [busy, setBusy] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  // Seed the form from the category whenever the modal opens.
  React.useEffect(() => {
    if (!open || !category) return;
    setError(null);
    setBusy(false);
    setType(inferDefaultType(category));
    setExistingId("__new__");
    setName(category.categoryName ?? "");
    setParentId("__top__");
    setPrice("");
    setPeriod("monthly");
    setEffectiveFrom(firstOfCurrentMonthIso());
  }, [open, category]);

  const dollarsToCents = (v: string) => Math.round((parseFloat(v) || 0) * 100);
  const priceCents = dollarsToCents(price);
  const isIncome = type === "income";
  const normalised = React.useMemo(() => normalisePeriods(priceCents, period), [priceCents, period]);
  const canSubmit = name.trim().length > 0 && !busy;

  const onSubmit = async () => {
    if (!canSubmit || !category) return;
    setBusy(true);
    setError(null);
    try {
      const mapToExisting = existingId !== "__new__";
      const res = await call("POST /api/categories/adopt", {
        categoryId: category.categoryId,
        // Mapping-only adopts still need the schema's name/type; they are
        // ignored server-side when existingEnvelopeId is present.
        name: mapToExisting ? (category.categoryName ?? category.categoryId) : name.trim(),
        type,
        ...(mapToExisting ? { existingEnvelopeId: existingId } : {}),
        // Guarded like the edit wizard's chronology: a cleared date input
        // yields "" which the server's strict date schema rejects — omit it
        // and the server keeps its own defaults.
        ...(effectiveFrom ? { effectiveFrom } : {}),
        ...(isIncome
          ? { budgetedCents: priceCents }
          : {
              budgetedCents: priceCents,
              period,
              parentId: parentId !== "__top__" ? parentId : null,
            }),
      });
      if (isApiError(res)) {
        setError(res.error);
        return;
      }
      invalidateAfterAdopt();
      onOpenChange(false);
    } catch (e) {
      setError(
        e instanceof ApiCallError || e instanceof Error ? e.message : "Could not add the category.",
      );
    } finally {
      setBusy(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Add category to budget</DialogTitle>
          <DialogDescription>
            {category?.categoryName
              ? `“${category.categoryName}” is on your transactions but not in your budget yet. Add it as an envelope.`
              : "This category is on your transactions but not in your budget yet. Add it as an envelope."}
          </DialogDescription>
        </DialogHeader>

        {/* Type toggle: Income / Expense / Saving / Envelope (default inferred). */}
        <div className="space-y-2">
          <Label>Type</Label>
          <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
            {TYPE_OPTIONS.map(({ value, label, icon: Icon }) => (
              <button
                key={value}
                type="button"
                onClick={() => setType(value)}
                className={cn(
                  "flex items-center justify-center gap-1.5 rounded-md border px-2 py-2 text-sm font-medium transition-colors",
                  type === value ? "border-primary bg-primary text-primary-foreground" : "hover:bg-accent",
                )}
              >
                <Icon className="h-4 w-4" /> {label}
              </button>
            ))}
          </div>
        </div>

        <div className="space-y-2">
          <Label htmlFor="adopt-name">Name</Label>
          <Input id="adopt-name" value={name} onChange={(e) => setName(e.target.value)} />
        </div>

        {!isIncome && (
          <div className="space-y-2">
            <Label>Parent / category</Label>
            <Select value={parentId} onValueChange={setParentId}>
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="__top__">Top level (no parent)</SelectItem>
                {rows.map((r) => (
                  <SelectItem key={r.id} value={r.id}>
                    {r.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        )}

        {isIncome ? (
          <div className="space-y-2">
            <Label htmlFor="adopt-income">Expected income — budget (AUD)</Label>
            <Input
              id="adopt-income"
              type="number"
              min="0"
              step="0.01"
              inputMode="decimal"
              placeholder="0.00"
              value={price}
              onChange={(e) => setPrice(e.target.value)}
            />
            <p className="text-xs text-muted-foreground">
              The expected income for this source. It is the figure the zero-base balances against.
            </p>
          </div>
        ) : (
          <div className="space-y-3">
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label htmlFor="adopt-price">Budget (AUD)</Label>
                <Input
                  id="adopt-price"
                  type="number"
                  min="0"
                  step="0.01"
                  inputMode="decimal"
                  placeholder="0.00"
                  value={price}
                  onChange={(e) => setPrice(e.target.value)}
                />
              </div>
              <div className="space-y-2">
                <Label>Period</Label>
                <Select value={period} onValueChange={(v) => setPeriod(v as BudgetPeriod)}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {BUDGET_PERIODS.map((p) => (
                      <SelectItem key={p} value={p}>
                        {BUDGET_PERIOD_LABELS[p]}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
            {/* Live equivalents across all four periods, recomputed as the user types. */}
            <div className="grid grid-cols-4 gap-2 rounded-md border bg-muted/40 p-2 text-center">
              {BUDGET_PERIODS.map((p) => (
                <div key={p} className={cn("rounded px-1 py-1", p === period && "bg-primary/10")}>
                  <div className="text-[10px] uppercase tracking-wide text-muted-foreground">
                    {BUDGET_PERIOD_LABELS[p]}
                  </div>
                  <div className="tnum text-sm font-medium">{formatCents(normalised[p])}</div>
                </div>
              ))}
            </div>
          </div>
        )}

        <div className="space-y-2">
          <Label htmlFor="adopt-start">Start date</Label>
          <Input
            id="adopt-start"
            type="date"
            value={effectiveFrom}
            onChange={(e) => setEffectiveFrom(e.target.value)}
          />
          <p className="text-xs text-muted-foreground">
            The budget and this category's transactions count from this date. Defaults to the first of the
            current month.
          </p>
          {category?.firstSeenDate && effectiveFrom && category.firstSeenDate < effectiveFrom && (
            <p className="text-xs text-warning">
              This category's transactions go back to {category.firstSeenDate}. Ones before the start date
              stay unbudgeted (back-date the start to include them). The category will not re-appear as new
              either way.
            </p>
          )}
        </div>

        {error && <p className="text-sm text-destructive">{error}</p>}

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button onClick={onSubmit} disabled={!canSubmit}>
            <Plus className="h-4 w-4" /> {busy ? "Adding…" : "Add to budget"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * New-category detection + adopt routes. A synced transaction can carry a
 * PocketSmith category that has no envelope mapping yet (distinct from an
 * uncategorised transaction, which has NO category at all): these routes list
 * those categories and let the user adopt each into the budget.
 *
 *   GET  /api/categories/unmapped  distinct unmapped categories with aggregates
 *   POST /api/categories/adopt     create envelope + mapping in one transaction
 *
 * Every route is scoped to the authenticated user (ISC-49); the adopt body is
 * validated with zod at the boundary (../validate.ts) before it reaches the
 * ledger, and the multi-write adopt runs inside one store transaction.
 */

import { Hono } from "hono";
import type { Container } from "../../composition.ts";
import type { Services } from "../services.ts";
import type {
  AdoptCategoryResponse,
  DismissCategoryResponse,
  DismissedCategoriesResponse,
  UnmappedCategoriesResponse,
} from "../contract.ts";
import { currentPeriod, resolveSession, UNAUTHENTICATED } from "../http.ts";
import { todayISO } from "../../platform/time.ts";
import { parseBody, adoptCategorySchema, dismissCategorySchema, dateParam, dateParamResponse } from "../validate.ts";

export function registerCategories(api: Hono, container: Container, services: Services): void {
  const tz = container.config.timezone;

  // Distinct categories present on transactions but not in the budget, most
  // transactions first. Optional from/to (YYYY-MM-DD) scope the scan; read raw
  // from the query to match the neighbouring grid handler's from/to handling.
  api.get("/categories/unmapped", async (c) => {
    const session = await resolveSession(c, container);
    if (!session) return c.json(UNAUTHENTICATED, 401);
    let from: string | undefined, to: string | undefined;
    try {
      from = dateParam("from", c.req.query("from"));
      to = dateParam("to", c.req.query("to"));
    } catch (err) {
      return dateParamResponse(c, err);
    }
    const categories = await services.envelopes.listUnmappedCategories(session.userId, {
      ...(from ? { from } : {}),
      ...(to ? { to } : {}),
      tz,
    });
    const res: UnmappedCategoriesResponse = { categories };
    return c.json(res);
  });

  // The cleared categories (Settings → Not synced): same aggregates as the
  // unmapped list, restricted to dismissed ids.
  api.get("/categories/dismissed", async (c) => {
    const session = await resolveSession(c, container);
    if (!session) return c.json(UNAUTHENTICATED, 401);
    const categories = await services.envelopes.listDismissedCategories(session.userId, tz);
    const res: DismissedCategoriesResponse = { categories };
    return c.json(res);
  });

  // Clear (dismiss) or restore one detected category. Dismissed categories
  // stop appearing on the budget page and list under Settings → Not synced.
  api.post("/categories/dismiss", async (c) => {
    const session = await resolveSession(c, container);
    if (!session) return c.json(UNAUTHENTICATED, 401);
    const parsed = await parseBody(c, dismissCategorySchema);
    if (!parsed.ok) return parsed.response;
    await services.envelopes.setCategoryDismissed(session.userId, parsed.value.categoryId, parsed.value.dismissed);
    const res: DismissCategoryResponse = { ok: true };
    return c.json(res);
  });

  // Adopt one category: create the envelope and seed the category→envelope
  // mapping in a single store transaction (BudgetService.adoptCategory). The
  // handler only resolves the timezone-dependent schedule anchor default.
  api.post("/categories/adopt", async (c) => {
    const session = await resolveSession(c, container);
    if (!session) return c.json(UNAUTHENTICATED, 401);
    const parsed = await parseBody(c, adoptCategorySchema);
    if (!parsed.ok) return parsed.response;
    const req = parsed.value;
    const envelopeId = await services.budget.adoptCategory(session.userId, currentPeriod(tz), {
      categoryId: req.categoryId,
      name: req.name,
      type: req.type,
      // The rollover sequence anchors where the budget starts: the client's
      // chosen start date when given, else today (the pre-start-date default).
      rolloverStart: req.effectiveFrom ?? todayISO(tz),
      ...(req.budgetedCents !== undefined ? { budgetedCents: req.budgetedCents } : {}),
      ...(req.period !== undefined ? { period: req.period } : {}),
      ...(req.rolloverRule !== undefined ? { rolloverRule: req.rolloverRule } : {}),
      ...(req.parentId !== undefined ? { parentId: req.parentId } : {}),
      ...(req.effectiveFrom !== undefined ? { effectiveFrom: req.effectiveFrom } : {}),
      ...(req.existingEnvelopeId !== undefined ? { existingEnvelopeId: req.existingEnvelopeId } : {}),
    });
    const res: AdoptCategoryResponse = { envelopeId };
    return c.json(res);
  });
}

/**
 * zod validation at every mutation boundary. One schema per POST body, derived
 * from the contract types (src/server/contract.ts), parsed with safeParse so a
 * malformed body is a uniform 400 ApiError — never an engine exception and
 * never silently-coerced garbage landing in the money ledger.
 *
 * Conventions enforced here:
 *   - Money is INTEGER cents: z.number().int() (floats and NaN are rejected).
 *   - Dates are strict YYYY-MM-DD strings.
 *   - Ids are non-empty strings.
 *
 * The schemas must accept everything the UI legitimately sends today (the
 * web call sites in web/src were read to confirm each optional field), and
 * reject everything else with a 400 in the existing { error, code } shape.
 */

import type { Context } from "hono";
import { z } from "zod";
import type { ApiError } from "./contract.ts";

// ── Shared field schemas ──────────────────────────────────────────────────────

/** Money: integer cents only. Rejects floats, NaN, and Infinity. */
export const centsSchema = z.number().int();

/** Strict calendar date, YYYY-MM-DD. */
export const isoDateSchema = z.string().regex(/^\d{4}-\d{2}-\d{2}$/, "expected YYYY-MM-DD");

/**
 * A date constrained to the plausible budgeting era. Every budget-window field
 * uses this: a partially-typed year (0002-08-01) must never mint a version or
 * materialise a month (the 1.4M-row garbage lesson, 2026-08-12).
 */
export const eraDateSchema = isoDateSchema.refine(
  (d) => d >= "1990-01-01" && d <= "2100-12-31",
  "date outside the supported era (1990..2100)",
);

/** Non-empty string id. */
export const idSchema = z.string().min(1);

export const changeScopeSchema = z.enum(["this_month", "ongoing"]);
export const budgetPeriodSchema = z.enum(["weekly", "fortnightly", "monthly", "annual"]);
export const envelopeTypeSchema = z.enum(["income", "expense", "saving", "envelope", "working"]);
export const rolloverRuleSchema = z.enum(["roll_carry", "drain_to_zero", "annual_reset"]);

// ── Request-body schemas (one per POST endpoint) ─────────────────────────────

/** POST /api/envelopes/move and POST /api/move (MoveMoneyRequest). */
export const moveMoneySchema = z.object({
  fromEnvelopeId: idSchema,
  toEnvelopeId: idSchema,
  amountCents: centsSchema,
  scope: changeScopeSchema,
});

/** POST /api/envelopes/distribute (DistributeRequest). */
export const distributeSchema = z.object({
  legs: z.array(z.object({ envelopeId: idSchema, deltaCents: centsSchema })),
  scope: changeScopeSchema,
});

/** POST /api/envelopes (CreateEnvelopeRequest). */
export const createEnvelopeSchema = z.object({
  name: z.string().trim().min(1),
  type: envelopeTypeSchema,
  parentId: idSchema.nullable().optional(),
  rolloverRule: rolloverRuleSchema.optional(),
  budgetedCents: centsSchema.optional(),
  period: budgetPeriodSchema.optional(),
  rolloverStart: isoDateSchema.optional(),
  active: z.boolean().optional(),
  targetCents: centsSchema.optional(),
  // Budget chronology: the first version's effective window (optional).
  effectiveFrom: eraDateSchema.optional(),
  effectiveTo: eraDateSchema.optional(),
});

/** POST /api/envelopes/edit (EditEnvelopeRequest). */
export const editEnvelopeSchema = z.object({
  id: idSchema,
  name: z.string().trim().min(1).optional(),
  type: envelopeTypeSchema.optional(),
  parentId: idSchema.nullable().optional(),
  active: z.boolean().optional(),
  budgetedCents: centsSchema.optional(),
  period: budgetPeriodSchema.optional(),
  targetCents: centsSchema.optional(),
  // Budget chronology: a budget change appends a new effective-dated version.
  effectiveFrom: eraDateSchema.optional(),
  effectiveTo: eraDateSchema.optional(),
  completePrevious: z.boolean().optional(),
  supersedeScheduled: z.boolean().optional(),
  asOf: eraDateSchema.optional(),
  expectedDay: z.number().int().min(1).max(31).nullable().optional(),
});

/** POST /api/envelopes/versions/edit (EditVersionRequest). */
export const editVersionSchema = z.object({
  envelopeId: idSchema,
  versionId: idSchema,
  amountCents: centsSchema.optional(),
  period: budgetPeriodSchema.optional(),
  effectiveFrom: eraDateSchema.optional(),
  effectiveTo: eraDateSchema.nullable().optional(),
  acceptAdjustments: z.boolean().optional(),
});

/** POST /api/categories/adopt (AdoptCategoryRequest). */
export const adoptCategorySchema = z.object({
  categoryId: idSchema,
  name: z.string().trim().min(1),
  existingEnvelopeId: idSchema.optional(),
  type: envelopeTypeSchema,
  budgetedCents: centsSchema.optional(),
  period: budgetPeriodSchema.optional(),
  rolloverRule: rolloverRuleSchema.optional(),
  parentId: idSchema.nullable().optional(),
  effectiveFrom: isoDateSchema.optional(),
});

/** POST /api/categories/dismiss (DismissCategoryRequest). */
export const dismissCategorySchema = z.object({
  categoryId: idSchema,
  dismissed: z.boolean(),
});

/** POST /api/envelopes/carryover (SetCarryoverRequest). */
export const setCarryoverSchema = z.object({
  envelopeId: idSchema,
  carryoverCents: centsSchema,
});

/** POST /api/envelopes/archive (ArchiveEnvelopeRequest). */
export const archiveEnvelopeSchema = z.object({
  envelopeId: idSchema,
  archived: z.boolean(),
});

/** POST /api/envelopes/rollover (SetRolloverRequest). */
export const setRolloverSchema = z.object({
  envelopeId: idSchema,
  rolloverStart: isoDateSchema,
  period: budgetPeriodSchema.optional(),
});

/**
 * GET /api/carryover/history (CarryoverHistoryQuery). Query params arrive as
 * strings; an envelopeId, when present, must be non-empty (an explicit
 * `?envelopeId=` is a 400, never a silent unfiltered read).
 */
export const carryoverHistoryQuerySchema = z.object({
  envelopeId: idSchema.optional(),
});

/** POST /api/budget/edit (EditBudgetRequest). */
export const editBudgetSchema = z.object({
  lines: z.array(
    z.object({
      envelopeId: idSchema,
      amountCents: centsSchema,
      period: budgetPeriodSchema.optional(),
    }),
  ),
  scope: changeScopeSchema,
  // Budget chronology: the new version's effective window and whether the
  // previous open version(s) are completed the day before it starts.
  effectiveFrom: eraDateSchema.optional(),
  effectiveTo: eraDateSchema.optional(),
  completePrevious: z.boolean().optional(),
  supersedeScheduled: z.boolean().optional(),
  asOf: eraDateSchema.optional(),
});

/**
 * POST /api/reconcile (ReconcileRequest). The preview tolerates a cleared date
 * input ("" = as of now), matching the tolerant behaviour the UI relied on.
 */
export const reconcileSchema = z.object({
  nabStatementCents: centsSchema,
  statementDate: z.union([isoDateSchema, z.literal("")]),
});

/**
 * POST /api/reconcile/confirm (ReconcileConfirmRequest). Persisted, so the
 * statement date must be a real date — a "" here would corrupt the ledger.
 */
export const reconcileConfirmSchema = z.object({
  nabStatementCents: centsSchema,
  statementDate: isoDateSchema,
});

/** POST /api/settings/pocketsmith-key (SetPocketSmithKeyRequest). */
export const setPocketSmithKeySchema = z.object({
  developerKey: z.string().trim().min(1),
});

/** POST /api/auth/signin (SignInRequest). */
export const signInSchema = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("pin"), pin: z.string().min(1) }),
  z.object({ kind: z.literal("email"), email: z.string().min(1) }),
]);

/** POST /api/auth/verify (VerifyLinkRequest). */
export const verifyLinkSchema = z.object({ token: z.string().min(1) });

/** POST /api/auth/change-pin (ChangePinRequest). */
export const changePinSchema = z.object({
  currentPin: z.string().min(1),
  newPin: z.string().min(1),
});

// ── Query-param date guard ────────────────────────────────────────────────────

/**
 * Validate an optional from/to/asOf date QUERY param. GET params were read raw,
 * and browser date inputs emit partial years while the user types (0002-08-01,
 * 0020-08-01, ...) — those reached ensureMonth and materialised ~1.4M garbage
 * allocation rows spanning years 10..1015. Anything malformed or outside the
 * plausible era is a 400, never a silent read (or write) of a garbage month.
 * Returns the value (or undefined when absent); throws DateParamError.
 */
export class DateParamError extends Error {
  constructor(name: string, value: string) {
    super(`Invalid ${name} date "${value}": expected YYYY-MM-DD between 1990 and 2100.`);
  }
}

export function dateParam(name: string, value: string | undefined): string | undefined {
  if (value === undefined || value === "") return undefined;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value) || value < "1990-01-01" || value > "2100-12-31") {
    throw new DateParamError(name, value);
  }
  return value;
}

/** Uniform 400 for a DateParamError; rethrows anything else. */
export function dateParamResponse(c: Context, err: unknown): Response {
  if (err instanceof DateParamError) {
    const body: ApiError = { error: err.message, code: "bad_request" };
    return c.json(body, 400);
  }
  throw err;
}

// ── The boundary helper ───────────────────────────────────────────────────────

export type ParsedBody<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly response: Response };

/**
 * Parse and validate a JSON request body against a schema. On any failure —
 * unparseable JSON or a schema violation — returns a ready-made 400 in the
 * uniform ApiError shape, naming the first offending field (values are never
 * echoed back).
 */
export async function parseBody<S extends z.ZodTypeAny>(
  c: Context,
  schema: S,
): Promise<ParsedBody<z.infer<S>>> {
  const raw: unknown = await c.req.json().catch(() => undefined);
  const result = schema.safeParse(raw);
  if (!result.success) {
    const issue = result.error.issues[0];
    const at = issue && issue.path.length > 0 ? ` at ${issue.path.join(".")}` : "";
    const err: ApiError = {
      error: `Invalid request body${at}: ${issue?.message ?? "malformed JSON"}.`,
      code: "bad_request",
    };
    return { ok: false, response: c.json(err, 400) };
  }
  return { ok: true, value: result.data as z.infer<S> };
}

/**
 * The GET twin of parseBody: validate a request's query params against a
 * schema. Hono's c.req.query() yields Record<string, string>, so schemas here
 * describe string-shaped fields. Failures return the same uniform 400 ApiError
 * (first offending field named, values never echoed back).
 */
export function parseQuery<S extends z.ZodTypeAny>(c: Context, schema: S): ParsedBody<z.infer<S>> {
  const result = schema.safeParse(c.req.query());
  if (!result.success) {
    const issue = result.error.issues[0];
    const at = issue && issue.path.length > 0 ? ` at ${issue.path.join(".")}` : "";
    const err: ApiError = {
      error: `Invalid query${at}: ${issue?.message ?? "malformed query"}.`,
      code: "bad_request",
    };
    return { ok: false, response: c.json(err, 400) };
  }
  return { ok: true, value: result.data as z.infer<S> };
}

