497	  /** Time-travel grid: balances as at end-of-day `asOfDate` (ISC-36 data side). */
498	  async getGridAsOf(userId: UserId, asOfDate: string): Promise<GridResponse> {
499	    const period = periodOfDate(asOfDate);
500	    return this.buildGrid(userId, { from: period, to: period }, asOfDate);
