502	
503	  private async buildGrid(
504	    userId: UserId,
505	    range: MonthRange,
506	    asOf?: string,
507	    includeArchived = false,
508	  ): Promise<GridResponse> {
509	    const target = range.to;
510	    const [allEnvelopes, txs, mappings, envelopeCarryover, template] = await Promise.all([
511	      this.store.listEnvelopes(userId),
512	      this.store.listTransactions(userId),
513	      this.store.listMappings(userId),
514	      this.store.listEnvelopeCarryover(userId),
515	      this.store.listTemplate(userId),
516	    ]);
517	    // Archived envelopes are excluded ENTIRELY from the grid: not shown, not in any
518	    // total, not in the zero-base (their transactions still resolve via the surviving
519	    // mappings, the envelope is simply hidden). getDetail opts back in so the detail
520	    // page can still load an archived envelope to unarchive it.
521	    const envelopes = includeArchived
522	      ? allEnvelopes
523	      : allEnvelopes.filter((e) => e.archived !== true);
524	    // Working envelopes are tracked (they keep their rows and actuals) but sit OUTSIDE
525	    // the zero-based budget: their allocations are excluded from budgetedOut so the
526	    // residual is unchanged by them.
527	    const workingIds = new Set(
528	      envelopes.filter((e) => (e.type ?? "expense") === "working").map((e) => e.id),
529	    );
530	    // Per-row budget period label: the CURRENT version's cadence (the line
531	    // contributing to the target month with the latest effectiveFrom).
532	    const templatePeriods = new Map<string, BudgetPeriod>();
533	    for (const e of envelopes) {
534	      const line = currentLineFor(template, e.id, target);
535	      if (line !== null) templatePeriods.set(e.id, line.period ?? "monthly");
536	    }
537	
538	    // The imported rollover baseline (ISC-25..28, ISC-85): each envelope's carried
539	    // starting balance as captured from PocketSmith. When present it is the opening
540	    // carryover entering the range's first month, so the fold starts at range.from
541	    // and rolls only forward (the baseline already encapsulates prior history).
542	    const openingCarryover = new Map(
543	      envelopeCarryover.filter((c) => c.carryoverCents !== 0).map((c) => [c.envelopeId, c.carryoverCents]),
544	    );
545	
546	    // With no baseline, fold from the earliest month that has activity (legacy
547	    // path, used by the engine tests). With a baseline, start at range.from.
548	    let start = range.from;
549	    if (openingCarryover.size === 0) {
550	      for (const tx of txs) {
551	        const p = periodOfDate(tx.date);
552	        if (comparePeriods(p, start) < 0) start = p;
553	      }
554	    }
555	    if (comparePeriods(start, range.from) > 0) start = range.from;
556	
557	    const periods = periodRange(start, target);
558	    const inputs: PeriodInputs[] = [];
559	    for (const p of periods) {
560	      const allocs = await this.store.listAllocations(userId, periodKey(p));
561	      const allocationByEnv = new Map<string, number>();
562	      for (const a of allocs) {
563	        allocationByEnv.set(a.envelopeId, (allocationByEnv.get(a.envelopeId) ?? 0) + a.amountCents);
564	      }
565	      const isFinal = comparePeriods(p, target) === 0;
566	      // The budget grid counts pending non-transfer spend in Spent/Left
567	      // (includePending). Transfers stay excluded. The holding tripwire
568	      // (holdingBalance) and reconcile keep the posted-only rule, so this does
569	      // not move any bank-reconciliation figure.
570	      const activity = computeActivity(txs, mappings, this.config, {
571	        period: p,
572	        includePending: true,
573	        ...(isFinal && asOf !== undefined ? { asOf } : {}),
574	      });
575	      inputs.push({ period: p, allocationByEnv, activityByEnv: activity.byEnvelope });
576	    }
577	
578	    const fold = foldPeriods(envelopes, inputs, openingCarryover);
579	
580	    // The visible range is [range.from .. target]; everything before range.from was
581	    // only folded to produce the opening carryover. Aggregate the per-period rolled
582	    // snapshots across the visible months: carryover is the opening at range.from,
