385	   * In-place mutation is audited: a budget_history row plus a version.edit
386	   * event carry the before/after, so the append-only spirit survives the edit.
387	   */
388	  async editVersion(
389	    userId: UserId,
390	    period: Period,
391	    input: {
392	      readonly envelopeId: string;
393	      readonly versionId: string;
394	      readonly amountCents?: number;
395	      readonly period?: BudgetPeriod;
396	      readonly effectiveFrom?: string;
397	      readonly effectiveTo?: string | null;
398	      readonly acceptAdjustments?: boolean;
399	    },
400	  ): Promise<{ ok: true; applied: readonly NeighbourAdjustment[] }> {
401	    return this.store.withTransaction(async () => {
402	      const template = await this.store.listTemplate(userId);
403	      const lines = template.filter((t) => t.envelopeId === input.envelopeId && !isTombstone(t));
404	      const target = lines.find((l) => l.id === input.versionId);
405	      if (!target) throw new Error("Budget version not found.");
406	
407	      const newFrom = input.effectiveFrom ?? effectiveFromOf(target);
408	      const newTo = input.effectiveTo === undefined ? effectiveToOf(target) : input.effectiveTo;
409	      const newAmount = input.amountCents ?? target.amountCents;
410	      assertWindow(newFrom, newTo);
411	
412	      // Neighbours by window order (live lines only, excluding the target).
413	      const others = lines.filter((l) => l.id !== target.id);
414	      const predecessor = others
415	        .filter((l) => effectiveFromOf(l) < newFrom)
416	        .sort((a, b) => effectiveFromOf(b).localeCompare(effectiveFromOf(a)))[0];
417	      const successor = others
418	        .filter((l) => effectiveFromOf(l) > newFrom)
419	        .sort((a, b) => effectiveFromOf(a).localeCompare(effectiveFromOf(b)))[0];
420	
421	      type Adjustment = {
422	        versionId: string;
423	        field: "effectiveTo";
424	        current: string | null;
425	        suggested: string;
426	        required: boolean;
427	        note: string;
428	      };
429	      const adjustments: Adjustment[] = [];
430	      if (predecessor) {
431	        const predTo = effectiveToOf(predecessor) ?? "9999-12-31";
432	        const cutoff = previousDay(newFrom);
433	        if (predTo >= newFrom) {
434	          adjustments.push({
435	            versionId: predecessor.id,
436	            field: "effectiveTo",
437	            current: effectiveToOf(predecessor),
438	            suggested: cutoff,
439	            required: true,
440	            note: `End the previous budget on ${cutoff} so the two never overlap.`,
441	          });
442	        } else if (predTo < cutoff) {
443	          adjustments.push({
444	            versionId: predecessor.id,
445	            field: "effectiveTo",
446	            current: effectiveToOf(predecessor),
447	            suggested: cutoff,
448	            required: false,
449	            note: `Extend the previous budget to ${cutoff} so the budgets line up with no gap.`,
450	          });
451	        }
452	      }
453	      if (successor && (newTo === null || newTo >= effectiveFromOf(successor))) {
454	        const cap = previousDay(effectiveFromOf(successor));
455	        adjustments.push({
456	          versionId: target.id,
457	          field: "effectiveTo",
