export interface EditVersionRequest {
  readonly envelopeId: string;
  readonly versionId: string;
  readonly amountCents?: number;
  /** Cadence label for the version (amount stays monthly-equivalent). */
  readonly period?: BudgetPeriod;
  readonly effectiveFrom?: string;
  /** New end date; explicit null clears it (open-ended). Omitted = unchanged. */
  readonly effectiveTo?: string | null;
  readonly acceptAdjustments?: boolean;
}

/** One suggested neighbour (or self-cap) change accompanying a window edit. */
export interface NeighbourAdjustment {
  /** The version the adjustment applies to (may be the edited version itself). */
  readonly versionId: string;
  readonly field: "effectiveTo";
  readonly current: string | null;
  readonly suggested: string;
  /** Required adjustments enforce non-overlap; optional ones close gaps. */
  readonly required: boolean;
  readonly note: string;
}

export interface EditVersionResponse {
  readonly ok: true;
  /** The adjustments actually applied alongside the edit. */
  readonly applied: readonly NeighbourAdjustment[];
}

// ── Settings ──────────────────────────────────────────────────────────────────

export interface SettingsResponse {
  readonly deployMode: "local" | "cloud";
  readonly hasPocketSmithKey: boolean;
  readonly lastSyncAt: string | null;
}

  "POST /api/auth/change-pin": true,
