1	import * as React from "react";
2	import { Pencil } from "lucide-react";
3	import type { BudgetVersionView, NeighbourAdjustment } from "@contract";
4	import { call, isApiError, ApiCallError } from "@/lib/api";
5	import { useEnvelopeVersions, useInvalidateBudget } from "@/lib/queries";
6	import { cn, formatCents, displayInPeriod, monthlyEquivalentCents, BUDGET_PERIODS, BUDGET_PERIOD_LABELS } from "@/lib/utils";
7	import type { BudgetPeriod } from "@domain";
8	import { Badge } from "@/components/ui/badge";
9	import { Button } from "@/components/ui/button";
10	import { Input } from "@/components/ui/input";
11	import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from "@/components/ui/select";
12	
13	/**
14	 * Budget chronology for one envelope (Phase 3): every effective-dated version
15	 * — completed, active, scheduled — most recent first, with date range, amount,
16	 * cadence, and a status chip. With `editable`, each real version opens an
17	 * inline editor (amount + window). Window edits that touch the neighbours come
18	 * back as a 409 with SUGGESTED adjustments ("end the previous budget on X so
19	 * they line up") and the user confirms or declines the optional ones — the
20	 * owner's prompt-on-save flow (2026-08-12). Data is the real versions
21	 * endpoint, never invented (ISC-83).
22	 */
23	
24	const STATUS_STYLE: Record<BudgetVersionView["status"], string> = {
25	  active: "border-success/40 bg-success/10 text-success",
26	  scheduled: "border-warning/40 bg-warning/10 text-warning",
27	  completed: "border-border bg-muted text-muted-foreground",
28	};
29	
30	function rangeLabel(v: BudgetVersionView): string {
31	  const from = v.effectiveFrom === "1970-01-01" ? "Start" : v.effectiveFrom;
32	  return v.effectiveTo === null ? `${from} → ongoing` : `${from} → ${v.effectiveTo}`;
33	}
34	
35	/** The legacy synthetic income row (no stored versions yet) cannot be edited in place. */
36	const isSynthetic = (v: BudgetVersionView): boolean => v.id.endsWith(":current");
37	
38	function VersionEditor({ envelopeId, version, onClose }: { envelopeId: string; version: BudgetVersionView; onClose: () => void }) {
39	  const invalidateBudget = useInvalidateBudget();
40	  // The amount is entered in the version's cadence (weekly/fortnightly/monthly/
41	  // annual — owner request 2026-08-12) and converts to its monthly equivalent.
42	  const [period, setPeriod] = React.useState<BudgetPeriod>(version.period);
43	  const [amount, setAmount] = React.useState((displayInPeriod(version.amountCents, version.period) / 100).toFixed(2));
44	  const [from, setFrom] = React.useState(version.effectiveFrom === "1970-01-01" ? "" : version.effectiveFrom);
45	  const [to, setTo] = React.useState(version.effectiveTo ?? "");
46	  const [busy, setBusy] = React.useState(false);
47	  const [error, setError] = React.useState<string | null>(null);
48	  const [adjustments, setAdjustments] = React.useState<readonly NeighbourAdjustment[] | null>(null);
49	
50	  const save = async (accept?: boolean) => {
51	    setBusy(true);
52	    setError(null);
53	    try {
54	      const res = await call("POST /api/envelopes/versions/edit", {
55	        envelopeId,
56	        versionId: version.id,
57	        amountCents: monthlyEquivalentCents(Math.round((parseFloat(amount) || 0) * 100), period),
58	        period,
59	        ...(from ? { effectiveFrom: from } : {}),
60	        effectiveTo: to ? to : null,
61	        ...(accept !== undefined ? { acceptAdjustments: accept } : {}),
62	      });
63	      if (isApiError(res)) {
64	        if (res.code === "neighbour_adjustments" && res.adjustments) setAdjustments(res.adjustments);
65	        else setError(res.error);
66	        return;
67	      }
68	      invalidateBudget();
69	      onClose();
70	    } catch (e) {
71	      if (e instanceof ApiCallError && e.code === "neighbour_adjustments") {
72	        // The suggestions travel in the error body; surface the message and
73	        // let the user decide (details are in the note text).
74	        setAdjustments([]);
75	        setError(e.message);
76	      } else {
77	        setError(e instanceof Error ? e.message : "Could not save the budget version.");
78	      }
79	    } finally {
80	      setBusy(false);
81	    }
82	  };
83	
84	  return (
85	    <div className="space-y-2 border-t bg-card px-4 py-3 text-xs">
86	      <div className="grid grid-cols-1 gap-2 sm:grid-cols-4">
87	        <label className="space-y-1">
88	          <span className="text-muted-foreground">Amount ($)</span>
89	          <Input type="number" min="0" step="0.01" className="h-8" value={amount} onChange={(e) => setAmount(e.target.value)} />
90	        </label>
91	        <label className="space-y-1">
92	          <span className="text-muted-foreground">Period</span>
93	          <Select value={period} onValueChange={(v) => setPeriod(v as BudgetPeriod)}>
94	            <SelectTrigger className="h-8" aria-label="Version period">
95	              <SelectValue />
96	            </SelectTrigger>
97	            <SelectContent>
98	              {BUDGET_PERIODS.map((p) => (
99	                <SelectItem key={p} value={p}>
100	                  {BUDGET_PERIOD_LABELS[p]}
101	                </SelectItem>
102	              ))}
103	            </SelectContent>
104	          </Select>
105	        </label>
106	        <label className="space-y-1">
107	          <span className="text-muted-foreground">Starts</span>
108	          <Input type="date" className="h-8" value={from} onChange={(e) => setFrom(e.target.value)} />
109	        </label>
110	        <label className="space-y-1">
111	          <span className="text-muted-foreground">Ends (blank = ongoing)</span>
112	          <Input type="date" className="h-8" value={to} min={from || undefined} onChange={(e) => setTo(e.target.value)} />
113	        </label>
114	      </div>
115	      {adjustments !== null && (
116	        <div className="space-y-2 rounded-md border border-warning/40 bg-warning/10 px-3 py-2">
117	          {adjustments.length > 0 ? (
118	            <ul className="list-disc space-y-1 pl-4">
119	              {adjustments.map((a, i) => (
120	                <li key={i}>
121	                  {a.note} {a.required ? <span className="font-medium">(required)</span> : <span>(suggested)</span>}
122	                </li>
123	              ))}
124	            </ul>
125	          ) : (
126	            <p>{error}</p>
127	          )}
128	          <div className="flex gap-2">
129	            <Button size="sm" variant="outline" disabled={busy} onClick={() => void save(true)}>
130	              Apply suggested updates
131	            </Button>
132	            <Button size="sm" variant="ghost" disabled={busy} onClick={() => void save(false)}>
133	              Save without optional updates
134	            </Button>
135	          </div>
136	        </div>
137	      )}
138	      {error && adjustments === null && <p className="text-destructive">{error}</p>}
139	      <div className="flex gap-2">
140	        <Button size="sm" disabled={busy} onClick={() => void save()}>
141	          {busy ? "Saving…" : "Save version"}
142	        </Button>
143	        <Button size="sm" variant="ghost" disabled={busy} onClick={onClose}>
144	          Cancel
145	        </Button>
146	      </div>
147	    </div>
148	  );
149	}
150	
151	export function VersionChronology({ envelopeId, editable = false }: { envelopeId: string; editable?: boolean }) {
152	  const query = useEnvelopeVersions(envelopeId);
153	  const data = query.data && !isApiError(query.data) ? query.data : null;
154	  const [editing, setEditing] = React.useState<string | null>(null);
155	
156	  if (query.isLoading) {
157	    return (
158	      <div className="px-4 py-3 text-xs text-muted-foreground animate-pulse">Loading budget history…</div>
159	    );
160	  }
161	  if (query.isError || (query.data && isApiError(query.data))) {
162	    return <div className="px-4 py-3 text-xs text-destructive">Could not load the budget history.</div>;
163	  }
164	  const versions = data?.versions ?? [];
165	  if (versions.length === 0) {
166	    return <div className="px-4 py-3 text-xs text-muted-foreground">No budget versions yet.</div>;
167	  }
168	
169	  return (
170	    <ol className="divide-y divide-border/40 border-t bg-muted/20" aria-label="Budget version chronology">
171	      {versions.map((v) => (
172	        <li key={v.id}>
173	          <div className="flex flex-wrap items-center gap-x-3 gap-y-1 px-4 py-2 text-xs">
174	            <span className="tnum min-w-0 text-muted-foreground">{rangeLabel(v)}</span>
175	            <span className="tnum font-medium">{formatCents(v.amountCents)}/mo</span>
176	            <span className="text-muted-foreground">{BUDGET_PERIOD_LABELS[v.period]}</span>
177	            <Badge variant="outline" className={cn("ml-auto px-1.5 py-0 text-[10px] capitalize", STATUS_STYLE[v.status])}>
178	              {v.status}
179	            </Badge>
180	            {editable && !isSynthetic(v) && (
181	              <button
