/** The summed (day-weighted) month-resolved amount for ONE envelope's lines in month M. */
export function resolveAmountForMonth(
  lines: readonly BudgetTemplate[],
  envelopeId: string,
  month: Period,
): number {
  let sum = 0;
  for (const line of lines) {
    if (line.envelopeId !== envelopeId) continue;
    sum += lineContributionForMonth(line, month);
  }
  return sum;
}

/**
 * The single line to adjust for an in-place delta edit (move-money /
 * distribute keep today's adjust-the-ongoing-plan semantics rather than
 * versioning every rebalance): the line contributing to `month` with the
 * greatest effectiveFrom, or null when none contributes.
 */
export function currentLineFor(
  lines: readonly BudgetTemplate[],
  envelopeId: string,
  month: Period,
): BudgetTemplate | null {
  let best: BudgetTemplate | null = null;
  for (const line of lines) {
    if (line.envelopeId !== envelopeId) continue;
