}

/**
 * Calendar day before an ISO date (pure calendar arithmetic; no timezone is
 * involved because both sides are already local calendar dates). Used by
 * completePrevious: the previous version ends the day before the new one starts.
 */
export function previousDay(isoDate: string): string {
  const d = new Date(`${isoDate}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() - 1);
  return d.toISOString().slice(0, 10);
}

/**
 * An income envelope's monthly budget for month M. Income budgets version
 * through the SAME effective-dated template lines (keyed by the income envelope
 * id). An income with no version lines at all falls back to the stored
 * `budgetedCents` (legacy back-compat: incomes budgets predate versioning);
 * once versions exist, resolution uses the SAME day-weighted proration the
 * expense resolvers use, so a mid-month income change prorates identically.
 */
export function resolveIncomeBudgetForMonth(
  lines: readonly BudgetTemplate[],
  income: IncomeEnvelope,
  month: Period,
): number {
  let hasLines = false;
  let sum = 0;
  for (const line of lines) {
    if (line.envelopeId !== income.id) continue;
    hasLines = true;
    sum += lineContributionForMonth(line, month);
  }
  return hasLines ? sum : income.budgetedCents;
}

/** Version status against the current (timezone-derived) month. */
export type VersionStatus = "completed" | "active" | "scheduled";

export function versionStatus(line: BudgetTemplate, now: Period): VersionStatus {
  if (comparePeriods(periodOfDate(effectiveFromOf(line)), now) > 0) return "scheduled";
  const to = effectiveToOf(line);
  if (to !== null && comparePeriods(periodOfDate(to), now) < 0) return "completed";
  return "active";
}

