1	/**
2	 * The four-figure rollup and the carryover fold (ISC-70, ISC-73, ISC-74,
3	 * ISC-75 data side, ISC-25..28).
4	 *
5	 * Every envelope row carries four figures:
6	 *   carryover  starting carryover from the prior period (signed)
7	 *   allocation this period's allocation
8	 *   total      carryover + allocation
9	 *   left       total - spent  (== total + signed activity)
10	 *
11	 * A parent is itself spendable and allocatable (ISC-73). Its figures are the
12	 * sum of its children's figures plus its own direct allocation and activity
13	 * (ISC-74). Carryover rolls per envelope on the envelope's own direct left, so
14	 * a parent's rolled carryover is the sum of its children's carryover plus its
15	 * own (deficits conserved, ISC-28).
16	 */
17	
18	import type { Envelope } from "../platform/store.ts";
19	import type { Period } from "../domain/types.ts";
20	import { carryoverInto, normaliseRolloverRule } from "./rules.ts";
21	import { comparePeriods, nextPeriod } from "./period.ts";
22	
23	/** Direct (non-rolled) figures for a single envelope in one period. */
24	export interface DirectFigures {
25	  readonly carryoverCents: number;
26	  readonly allocationCents: number;
27	  /** Signed net activity (negative = outflow). */
28	  readonly activityCents: number;
29	}
30	
31	/** Rolled figures: a node's own direct figures plus all descendants. */
32	export interface RolledFigures {
33	  readonly envelopeId: string;
34	  readonly carryoverCents: number;
35	  readonly allocationCents: number;
36	  readonly totalCents: number;
37	  readonly leftCents: number;
38	  readonly depth: number;
39	}
40	
41	/** Per-period engine input: the allocation and activity maps for that month. */
42	export interface PeriodInputs {
43	  readonly period: Period;
44	  readonly allocationByEnv: ReadonlyMap<string, number>;
45	  readonly activityByEnv: ReadonlyMap<string, number>;
46	}
47	
48	/** The direct left of a node: carryover + allocation + signed activity. */
49	export function directLeft(d: DirectFigures): number {
50	  return d.carryoverCents + d.allocationCents + d.activityCents;
51	}
52	
53	/** depth of every envelope id (0 = top level), following parent_id chains. */
54	export function depths(envelopes: readonly Envelope[]): Map<string, number> {
55	  const byId = new Map(envelopes.map((e) => [e.id, e]));
56	  const cache = new Map<string, number>();
57	  const resolve = (id: string, seen: Set<string>): number => {
58	    const cached = cache.get(id);
59	    if (cached !== undefined) return cached;
60	    const e = byId.get(id);
61	    if (e === undefined || e.parentId === null || seen.has(id)) {
62	      cache.set(id, 0);
63	      return 0;
64	    }
65	    seen.add(id);
66	    const d = resolve(e.parentId, seen) + 1;
67	    cache.set(id, d);
68	    return d;
69	  };
70	  for (const e of envelopes) resolve(e.id, new Set());
71	  return cache;
72	}
73	
74	/** Children-of map for tree summation. */
75	function childrenOf(envelopes: readonly Envelope[]): Map<string | null, Envelope[]> {
76	  const m = new Map<string | null, Envelope[]>();
77	  for (const e of envelopes) {
78	    const arr = m.get(e.parentId) ?? [];
79	    arr.push(e);
80	    m.set(e.parentId, arr);
81	  }
82	  return m;
83	}
84	
85	/**
86	 * Roll direct figures up the tree (ISC-74). Returns one RolledFigures per
87	 * envelope where each node aggregates itself plus every descendant.
88	 */
89	export function rollUp(
90	  envelopes: readonly Envelope[],
91	  direct: ReadonlyMap<string, DirectFigures>,
92	): Map<string, RolledFigures> {
93	  const depthOf = depths(envelopes);
94	  const children = childrenOf(envelopes);
95	  const out = new Map<string, RolledFigures>();
96	
97	  const compute = (e: Envelope): RolledFigures => {
98	    const self = direct.get(e.id) ?? { carryoverCents: 0, allocationCents: 0, activityCents: 0 };
99	    let carry = self.carryoverCents;
100	    let alloc = self.allocationCents;
101	    let activity = self.activityCents;
102	    for (const child of children.get(e.id) ?? []) {
103	      const r = compute(child);
104	      carry += r.carryoverCents;
105	      alloc += r.allocationCents;
106	      // Reconstruct child signed activity: left - total.
107	      activity += r.leftCents - r.totalCents;
108	    }
109	    const total = carry + alloc;
110	    const left = total + activity;
111	    const rolled: RolledFigures = {
112	      envelopeId: e.id,
113	      carryoverCents: carry,
114	      allocationCents: alloc,
115	      totalCents: total,
116	      leftCents: left,
117	      depth: depthOf.get(e.id) ?? 0,
118	    };
119	    out.set(e.id, rolled);
120	    return rolled;
121	  };
122	
123	  for (const e of envelopes) if (e.parentId === null) compute(e);
124	  // Any orphan (parent missing) still gets computed standalone.
125	  for (const e of envelopes) if (!out.has(e.id)) compute(e);
126	  return out;
127	}
128	
129	/** Result of folding the carryover across a contiguous run of periods. */
130	export interface FoldResult {
131	  /** Direct figures per envelope at the final (target) period. */
132	  readonly direct: ReadonlyMap<string, DirectFigures>;
133	  /** Rolled figures per envelope at the final period. */
134	  readonly rolled: ReadonlyMap<string, RolledFigures>;
135	  /** Carryover each envelope would start the period AFTER the target with. */
136	  readonly carryoverOut: ReadonlyMap<string, number>;
137	  /** Per-period rolled snapshots, in input order (for multi-month assertions). */
138	  readonly perPeriod: readonly ReadonlyMap<string, RolledFigures>[];
139	}
140	
141	/**
142	 * Fold carryover across ordered periods (ISC-25..28). `inputs` must be a
143	 * contiguous, ascending run of periods. Starting carryover comes from
144	 * `openingCarryover` (default zero) and each period's left rolls into the next
145	 * via the envelope's rollover rule.
146	 */
147	export function foldPeriods(
148	  envelopes: readonly Envelope[],
149	  inputs: readonly PeriodInputs[],
150	  openingCarryover?: ReadonlyMap<string, number>,
151	): FoldResult {
152	  const ruleOf = new Map(envelopes.map((e) => [e.id, normaliseRolloverRule(e.rolloverRule)]));
153	  let carry = new Map<string, number>(openingCarryover ?? []);
154	  let lastDirect = new Map<string, DirectFigures>();
155	  let lastRolled = new Map<string, RolledFigures>();
156	  const perPeriod: Map<string, RolledFigures>[] = [];
157	
158	  for (let i = 0; i < inputs.length; i++) {
159	    const pin = inputs[i]!;
160	    if (i > 0 && comparePeriods(inputs[i - 1]!.period, pin.period) >= 0) {
161	      throw new Error("foldPeriods requires ascending, contiguous periods");
162	    }
163	
164	    const direct = new Map<string, DirectFigures>();
165	    for (const e of envelopes) {
166	      direct.set(e.id, {
167	        carryoverCents: carry.get(e.id) ?? 0,
168	        allocationCents: pin.allocationByEnv.get(e.id) ?? 0,
169	        activityCents: pin.activityByEnv.get(e.id) ?? 0,
170	      });
171	    }
172	    const rolled = rollUp(envelopes, direct);
173	    perPeriod.push(rolled);
174	    lastDirect = direct;
175	    lastRolled = rolled;
176	
177	    // Carry each envelope's own direct left into the next period.
178	    const into = nextPeriod(pin.period);
179	    const nextCarry = new Map<string, number>();
180	    for (const e of envelopes) {
181	      const rule = ruleOf.get(e.id) ?? "roll_carry";
182	      nextCarry.set(e.id, carryoverInto(rule, directLeft(direct.get(e.id)!), into));
183	    }
184	    carry = nextCarry;
185	  }
186	
187	  return { direct: lastDirect, rolled: lastRolled, carryoverOut: carry, perPeriod };
188	}
