 * A parent is itself spendable and allocatable (ISC-73). Its figures are the
 * sum of its children's figures plus its own direct allocation and activity
 * (ISC-74). Carryover rolls per envelope on the envelope's own direct left, so
 * a parent's rolled carryover is the sum of its children's carryover plus its
 * own (deficits conserved, ISC-28).
 */

import type { Envelope } from "../platform/store.ts";
import type { Period } from "../domain/types.ts";
import { carryoverInto, normaliseRolloverRule } from "./rules.ts";
import { comparePeriods, nextPeriod } from "./period.ts";

/** Direct (non-rolled) figures for a single envelope in one period. */
export interface DirectFigures {
  readonly carryoverCents: number;
  readonly allocationCents: number;
  /** Signed net activity (negative = outflow). */
  readonly activityCents: number;
}

/** Rolled figures: a node's own direct figures plus all descendants. */
export interface RolledFigures {
  readonly envelopeId: string;
  readonly carryoverCents: number;
  readonly allocationCents: number;
  readonly totalCents: number;
  readonly leftCents: number;
  readonly depth: number;
}

/** Per-period engine input: the allocation and activity maps for that month. */
export interface PeriodInputs {
  readonly period: Period;
  readonly allocationByEnv: ReadonlyMap<string, number>;
  readonly activityByEnv: ReadonlyMap<string, number>;
}

/** The direct left of a node: carryover + allocation + signed activity. */
export function directLeft(d: DirectFigures): number {
  return d.carryoverCents + d.allocationCents + d.activityCents;
}

/** depth of every envelope id (0 = top level), following parent_id chains. */
export function depths(envelopes: readonly Envelope[]): Map<string, number> {
  const byId = new Map(envelopes.map((e) => [e.id, e]));
  const cache = new Map<string, number>();
  const resolve = (id: string, seen: Set<string>): number => {
    const cached = cache.get(id);
    if (cached !== undefined) return cached;
    const e = byId.get(id);
    if (e === undefined || e.parentId === null || seen.has(id)) {
      cache.set(id, 0);
      return 0;
    }
    seen.add(id);
    const d = resolve(e.parentId, seen) + 1;
    cache.set(id, d);
    return d;
  };
  for (const e of envelopes) resolve(e.id, new Set());
  return cache;
}

/** Children-of map for tree summation. */
function childrenOf(envelopes: readonly Envelope[]): Map<string | null, Envelope[]> {
  const m = new Map<string | null, Envelope[]>();
  for (const e of envelopes) {
    const arr = m.get(e.parentId) ?? [];
    arr.push(e);
    m.set(e.parentId, arr);
  }
  return m;
}

/**
 * Roll direct figures up the tree (ISC-74). Returns one RolledFigures per
 * envelope where each node aggregates itself plus every descendant.
 */
export function rollUp(
  envelopes: readonly Envelope[],
  direct: ReadonlyMap<string, DirectFigures>,
): Map<string, RolledFigures> {
  const depthOf = depths(envelopes);
  const children = childrenOf(envelopes);
  const out = new Map<string, RolledFigures>();

  const compute = (e: Envelope): RolledFigures => {
    const self = direct.get(e.id) ?? { carryoverCents: 0, allocationCents: 0, activityCents: 0 };
    let carry = self.carryoverCents;
    let alloc = self.allocationCents;
    let activity = self.activityCents;
    for (const child of children.get(e.id) ?? []) {
      const r = compute(child);
      carry += r.carryoverCents;
      alloc += r.allocationCents;
      // Reconstruct child signed activity: left - total.
      activity += r.leftCents - r.totalCents;
    }
    const total = carry + alloc;
    const left = total + activity;
    const rolled: RolledFigures = {
      envelopeId: e.id,
      carryoverCents: carry,
      allocationCents: alloc,
      totalCents: total,
      leftCents: left,
      depth: depthOf.get(e.id) ?? 0,
    };
    out.set(e.id, rolled);
    return rolled;
  };

  for (const e of envelopes) if (e.parentId === null) compute(e);
  // Any orphan (parent missing) still gets computed standalone.
  for (const e of envelopes) if (!out.has(e.id)) compute(e);
  return out;
}

/** Result of folding the carryover across a contiguous run of periods. */
export interface FoldResult {
  /** Direct figures per envelope at the final (target) period. */
  readonly direct: ReadonlyMap<string, DirectFigures>;
  /** Rolled figures per envelope at the final period. */
  readonly rolled: ReadonlyMap<string, RolledFigures>;
  /** Carryover each envelope would start the period AFTER the target with. */
  readonly carryoverOut: ReadonlyMap<string, number>;
  /** Per-period rolled snapshots, in input order (for multi-month assertions). */
  readonly perPeriod: readonly ReadonlyMap<string, RolledFigures>[];
}

/**
 * Fold carryover across ordered periods (ISC-25..28). `inputs` must be a
 * contiguous, ascending run of periods. Starting carryover comes from
 * `openingCarryover` (default zero) and each period's left rolls into the next
 * via the envelope's rollover rule.
 */
export function foldPeriods(
  envelopes: readonly Envelope[],
  inputs: readonly PeriodInputs[],
  openingCarryover?: ReadonlyMap<string, number>,
): FoldResult {
  const ruleOf = new Map(envelopes.map((e) => [e.id, normaliseRolloverRule(e.rolloverRule)]));
  let carry = new Map<string, number>(openingCarryover ?? []);
  let lastDirect = new Map<string, DirectFigures>();
  let lastRolled = new Map<string, RolledFigures>();
  const perPeriod: Map<string, RolledFigures>[] = [];

  for (let i = 0; i < inputs.length; i++) {
    const pin = inputs[i]!;
    if (i > 0 && comparePeriods(inputs[i - 1]!.period, pin.period) >= 0) {
      throw new Error("foldPeriods requires ascending, contiguous periods");
    }

    const direct = new Map<string, DirectFigures>();
    for (const e of envelopes) {
      direct.set(e.id, {
        carryoverCents: carry.get(e.id) ?? 0,
        allocationCents: pin.allocationByEnv.get(e.id) ?? 0,
        activityCents: pin.activityByEnv.get(e.id) ?? 0,
      });
    }
    const rolled = rollUp(envelopes, direct);
    perPeriod.push(rolled);
    lastDirect = direct;
    lastRolled = rolled;

    // Carry each envelope's own direct left into the next period.
    const into = nextPeriod(pin.period);
    const nextCarry = new Map<string, number>();
    for (const e of envelopes) {
      const rule = ruleOf.get(e.id) ?? "roll_carry";
      nextCarry.set(e.id, carryoverInto(rule, directLeft(direct.get(e.id)!), into));
    }
    carry = nextCarry;
  }

  return { direct: lastDirect, rolled: lastRolled, carryoverOut: carry, perPeriod };
}

