      await this.adjustCurrentLine(userId, template, plan.toEnvelopeId, plan.toDeltaCents, period);
      await this.rederiveMaterialisedMonths(userId, plan.fromEnvelopeId, template);
      await this.rederiveMaterialisedMonths(userId, plan.toEnvelopeId, template);
    }

