 * NULL): the baseline value of each envelope was captured either at the last
 * manual carryover reset (the carryover.reset event's `on` date) or, failing
 * that, at the initial PocketSmith import (the earliest event of any kind).
 * Anchoring at capture — not at rollover_start — prevents double-counting
 * history that the captured balance already includes.
 */
export const CARRYOVER_ANCHOR_BACKFILL_SQL: readonly string[] = [
  // A: last manual reset per envelope wins.
  `UPDATE envelopes SET carryover_anchor = (
     SELECT MAX(json_extract(e.payload_json, '$.on')) FROM events e
     WHERE e.user_id = envelopes.user_id AND e.kind = 'carryover.reset'
       AND json_extract(e.payload_json, '$.envelopeId') = envelopes.id
