     SELECT date(MIN(e.ts) / 1000, 'unixepoch') FROM events e WHERE e.user_id = envelopes.user_id
   )
   WHERE carryover_anchor IS NULL AND EXISTS (
     SELECT 1 FROM events e WHERE e.user_id = envelopes.user_id
   )`,
];'''
