describe("running balance invariant — synthetic leaf fixture", () => {
  test("balance after the most-recent transaction equals the grid Left", async () => {
    const store = new MemoryStore();
    const envSvc = new EnvelopeService(store, CONFIG);
    const budget = new BudgetService(store, envSvc);

    const B = 20000; // $200/month
    await store.upsertEnvelope(USER, env("syn", { name: "Synthetic", type: "expense" }));
    await store.putTemplateLine(USER, { id: "bt-syn", userId: USER, envelopeId: "syn", amountCents: B, period: "monthly" });
    // No carryover baseline -> the grid folds from the earliest activity (prev month).
    await store.setEnvelopeCarryover(USER, "syn", 0, prevDay(1));

    const t1 = tx({ id: "syn-1", date: prevDay(15), amountCents: -5000, envelopeId: "syn" });
    const t2 = tx({ id: "syn-2", date: TODAY, amountCents: -3000, envelopeId: "syn" });
    await store.upsertTransactions(USER, [t1, t2]);

    await budget.ensureMonth(USER, PREV);
    await budget.ensureMonth(USER, CUR);

    const grid = await envSvc.getGrid(USER, CUR);
    const left = grid.rows.find((r) => r.id === "syn")!.leftCents;
    // Independent check: two months of budget less both spends.
    expect(left).toBe(2 * B + t1.amountCents + t2.amountCents); // 32000

    const balances = await envSvc.runningBalances(USER, "syn");
    expect(balances.get("syn-2")).toBe(left); // THE INVARIANT
    // Across the month boundary the balance rises by one budget then falls by the spend.
    expect(balances.get("syn-2")! - balances.get("syn-1")!).toBe(B + t2.amountCents);
  });
});

