/**
 * BudgetBuddy service worker (ISC-61).
 *
 * Caches a minimal offline app shell so the installed PWA opens without the
 * network. Read-only shell caching only: there is deliberately NO offline
 * transaction capture and NO write/sync queue (ISC-64 anti). API calls are
 * always network-only and never queued.
 *
 * Navigation (the HTML shell) is NETWORK-FIRST so a new deploy is picked up on
 * the next load instead of being frozen on a stale cached index.html. Only the
 * immutable hashed assets and icons are cache-first.
 */

const SHELL_CACHE = "budgetbuddy-shell-v4";
const SHELL_ASSETS = [
  "/",
  "/index.html",
  "/manifest.webmanifest",
  "/icons/icon.svg",
  "/icons/icon-192.png",
  "/icons/icon-512.png",
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(SHELL_CACHE).then((cache) => cache.addAll(SHELL_ASSETS)).then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== SHELL_CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);

  // Never cache or queue API traffic. Network-only; no offline write queue.
  if (url.pathname.startsWith("/api/")) return;

  const isShell = request.mode === "navigate" || url.pathname === "/" || url.pathname === "/index.html";

  if (isShell) {
// Register the service worker so the offline app shell caches and the app is
// installable (ISC-61, ISC-62). Registration is best-effort: it only succeeds
// over HTTPS / localhost, which is how the app is served (tailscale serve,
// ISC-63). The SW does no offline write queueing (ISC-64 anti).
if ("serviceWorker" in navigator) {
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("/sw.js").catch(() => {
      /* SW registration is non-fatal; the app still runs online. */
    });
  });
}

ReactDOM.createRoot(document.getElementById("root")!).render(
  <React.StrictMode>
    <QueryClientProvider client={queryClient}>
      <BrowserRouter>
