/** Reproduction probe: does closing a Select inside the Dialog close the Dialog? */
import * as React from "react";
import { describe, it, expect, mock } from "bun:test";
import { render, screen, fireEvent, waitFor } from "@testing-library/react";
import * as realApi from "@/lib/api";
import { TestQueryProvider } from "@/test/utils";

const call = mock(async () => ({}));
mock.module("@/lib/api", () => ({ ...realApi, call }));
const { AddBudgetModal } = await import("@/components/AddBudgetModal");

describe("select-close inside dialog", () => {
  it("escape on an open select closes ONLY the select", async () => {
    const onOpenChange = mock(() => {});
    render(
      <TestQueryProvider>
        <AddBudgetModal
          open
          rows={[{ id: "p1", name: "Parent One", parentId: null } as never]}
          onOpenChange={onOpenChange}
          editTarget={null}
        />
      </TestQueryProvider>
    );
    // Open the Parent select (combobox trigger).
    const triggers = screen.getAllByRole("combobox");
    expect(triggers.length).toBeGreaterThan(0);
    const parentTrigger = triggers[triggers.length - 1]!;
    fireEvent.pointerDown(parentTrigger, { button: 0, pointerId: 1 });
    fireEvent.click(parentTrigger);
    await waitFor(() => expect(screen.getAllByRole("option").length).toBeGreaterThan(0));
    // Close the select with Escape.
    fireEvent.keyDown(document.activeElement ?? document.body, { key: "Escape" });
    await waitFor(() => expect(screen.queryAllByRole("option")).toHaveLength(0));
    // The DIALOG must still be open: onOpenChange(false) must NOT have fired.
    const closedCalls = onOpenChange.mock.calls.filter((c) => c[0] === false);
    console.log("onOpenChange(false) calls after select escape:", closedCalls.length);
    expect(closedCalls.length).toBe(0);
  });
});
