import { Navigate, Route, Routes, useLocation } from "react-router-dom";
import { useSession } from "@/lib/session";
import { AppShell } from "@/layout/AppShell";
import { SignInPage } from "@/pages/SignInPage";
import { BudgetPage } from "@/pages/BudgetPage";
import { EnvelopeDetailPage } from "@/pages/EnvelopeDetailPage";
import { TransactionsPage } from "@/pages/TransactionsPage";
import { ReconcilePage } from "@/pages/ReconcilePage";
import { BalancePage } from "@/pages/BalancePage";
import { HistoryPage } from "@/pages/HistoryPage";
import { SettingsPage } from "@/pages/SettingsPage";
import { EditBudgetPage } from "@/pages/EditBudgetPage";

export default function App() {
  const { authenticated, loading } = useSession();
  const location = useLocation();

  if (loading) {
    return (
      <div className="flex h-dvh items-center justify-center text-muted-foreground">
        <span className="animate-pulse">Loading BudgetBuddy…</span>
      </div>
    );
  }

  if (!authenticated) {
    // Every route funnels to sign-in until the AuthProvider mints a session.
    if (location.pathname !== "/signin") return <Navigate to="/signin" replace />;
    return (
      <Routes>
        <Route path="/signin" element={<SignInPage />} />
        <Route path="*" element={<Navigate to="/signin" replace />} />
      </Routes>
    );
  }

  return (
    <AppShell>
      <Routes>
        <Route path="/" element={<BudgetPage />} />
        <Route path="/envelope/:id" element={<EnvelopeDetailPage />} />
        <Route path="/transactions" element={<TransactionsPage />} />
        <Route path="/balance" element={<BalancePage />} />
        <Route path="/reconcile" element={<ReconcilePage />} />
        <Route path="/history" element={<HistoryPage />} />
        <Route path="/edit-budget" element={<EditBudgetPage />} />
        <Route path="/settings" element={<SettingsPage />} />
        <Route path="/signin" element={<Navigate to="/" replace />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </AppShell>
  );
}
