// Reset the form when the modal OPENS (or the target changes) — keyed by
// value, not object identity: a parent passing a fresh editTarget object on
// every render must not re-run the reset mid-edit (that clobbered the
// seeded real start date back to the 1st, and user typing with it).
const resetKeyRef = React.useRef<string | null>(null);
React.useEffect(() => {
  const key = open ? `${editTarget?.id ?? "new"}:${editTarget?.addVersion === true}` : null;
  if (!open) {
    resetKeyRef.current = null;
    return;
  }
  if (resetKeyRef.current === key) return;
  resetKeyRef.current = key;
  setError(null);
  setBusy(false);
  if (editTarget) {
    setType(editTarget.type);
    setName(editTarget.name);
    setParentId(editTarget.parentId ?? "__top__");
    setRolloverRule("roll_carry");
    // Keep the row's own period (ISC-94): seed both the selector and the price
    // converted out of its stored monthly equivalent into that period.
    {
      const rowPeriod = editTarget.period ?? "monthly";
      setPeriod(rowPeriod);
      setPrice(centsToInput(displayInPeriod(editTarget.monthlyCents, rowPeriod)));
    }
    setRolloverStart(editTarget.rolloverStart ?? "");
    // Income seeds in its OWN cadence (the stored figure is monthly-equivalent).
    setTarget(centsToInput(displayInPeriod(editTarget.targetCents, editTarget.period ?? "monthly")));
    setExpectedDay(editTarget.expectedDay != null ? String(editTarget.expectedDay) : "");
    // Prefilled with the familiar first-of-month; once the chronology loads
    // (below) a REAL dated active version replaces it with its actual window.
    // A legacy open-since-forever (1970) budget keeps this default — the
    // "Currently effective since the start" note explains — so the field is
    // always prefilled. Add-version mode keeps the add-flow defaults.
    setEffectiveFrom(firstOfCurrentMonthIso());
    setEffectiveTo("");
    setScheduledConflict(null);
    seededWindowRef.current = editTarget.addVersion === true;
  } else {
    setType("expense");
    setName("");
    setParentId("__top__");
    setRolloverRule("roll_carry");
    setPeriod("monthly");
    setPrice("");
    setRolloverStart(todayIso());
    setTarget("");
    setExpectedDay("");
    setEffectiveFrom(firstOfCurrentMonthIso());
    setEffectiveTo("");
    setScheduledConflict(null);
  }
}, [open, editTarget]);

// Seed the window fields from the ACTIVE version exactly once per open —
// the async chronology must never clobber dates the user already touched.
const seededWindowRef = React.useRef(false);
React.useEffect(() => {
  if (!open || !isEdit || seededWindowRef.current || activeVersion === null) return;
  seededWindowRef.current = true;
  if (activeVersion.effectiveFrom !== "1970-01-01") {
    setEffectiveFrom(activeVersion.effectiveFrom);
    setEffectiveTo(activeVersion.effectiveTo ?? "");
  }
}, [open, isEdit, activeVersion]);

const dollarsToCents = (v: string) => Math.round((parseFloat(v) || 0) * 100);
const priceCents = dollarsToCents(price);

