  ...envelopes.map((e: any) => [e.id, e.name] as [string, string]),
  ...incomes.map((i: any) => [i.id, i.name] as [string, string]),
]);
const catToEnv = new Map(mappings.map((m: any) => [m.categoryId, m.envelopeId]));
const firstTxMonth = txs.reduce((min: string | null, t: any) => (min === null || t.date < min ? t.date : min), null)!.slice(0, 7);
const startDate = `${firstTxMonth}-01`;
const endDate = new Date().toISOString().slice(0, 10);
const events = await client.listEvents(user.id, startDate, endDate);
console.log(`[audit] ${events.length} events ${startDate}..${endDate}`);

const byCategory = new Map<string, SeriesEvent[]>();
for (const ev of events) {
  const cid = ev.category?.id;
  if (cid === undefined || ev.date === undefined) continue;
  const key = String(cid);
  if (!catToEnv.has(key)) continue;
  const arr = byCategory.get(key) ?? [];
  arr.push({
    seriesId: ev.series_id ?? 0,
    date: ev.date,
    amountCents: Math.abs(Math.round((ev.amount ?? 0) * 100)),
    repeatType: ev.repeat_type ?? "once",
    repeatInterval: ev.repeat_interval ?? 1,
  });
  byCategory.set(key, arr);
}

const nowKey = endDate.slice(0, 7);
const monthsBetween = (a: string, b: string): string[] => {
  const out: string[] = [];
  let [y, m] = a.split("-").map(Number);
  while (`${y}-${String(m).padStart(2, "0")}` <= b) {
    out.push(`${y}-${String(m).padStart(2, "0")}`);
    m++; if (m > 12) { m = 1; y++; }
  }
  return out;
};

let clean = 0;
const reports: string[] = [];
for (const [catId, evs] of [...byCategory.entries()].sort((a, b) => (nameOf.get(catToEnv.get(a[0])!) ?? "").localeCompare(nameOf.get(catToEnv.get(b[0])!) ?? ""))) {
  const envelopeId = catToEnv.get(catId)!;
  const name = nameOf.get(envelopeId) ?? envelopeId;
  const eras = erasFromSeries(evs);
  if (eras.length === 0) continue;
  const lines = template.filter((l: any) => l.envelopeId === envelopeId && !isTombstone(l));
  // PS amount per month from eras; BB from resolveAmountForMonth.
  const psFor = (key: string): number | null => {
    const day = `${key}-15`;
    const era = eras.find((e: any) => e.from <= day && (e.to === null || e.to >= day));
    return era ? era.amountCents : null;
  };
  const firstEra = eras.reduce((min: string, e: any) => (e.from < min ? e.from : min), eras[0].from).slice(0, 7);
  const diffs: { from: string; to: string; ps: number | null; bb: number }[] = [];
  for (const key of monthsBetween(firstEra, nowKey)) {
    const ps = psFor(key);
    const bb = resolveAmountForMonth(lines, envelopeId, { year: Number(key.slice(0, 4)), month: Number(key.slice(5, 7)) });
    const same = ps !== null && Math.abs(ps - bb) <= 1; // 1c rounding tolerance
    if (same || (ps === null && bb === 0)) continue;
    const last = diffs[diffs.length - 1];
    if (last && last.ps === ps && last.bb === bb && last.to === prevKey(key)) last.to = key;
    else diffs.push({ from: key, to: key, ps, bb });
  }
  function prevKey(k: string): string {
    let [y, m] = k.split("-").map(Number);
    m--; if (m < 1) { m = 12; y--; }
    return `${y}-${String(m).padStart(2, "0")}`;
  }
  if (diffs.length === 0) { clean++; continue; }
  const eraStr = eras.map((e: any) => `${e.from}→${e.to ?? "…"} $${(e.amountCents / 100).toFixed(2)}`).join(", ");
  const lineStr = lines
    .sort((a: any, b: any) => (a.effectiveFrom ?? "").localeCompare(b.effectiveFrom ?? ""))
    .map((l: any) => `${l.effectiveFrom ?? "start"}→${l.effectiveTo ?? "…"} $${(l.amountCents / 100).toFixed(2)}/mo(${l.period ?? "monthly"})`).join(", ");
  reports.push(
    `## ${name} (${envelopeId})\n  PS eras: ${eraStr}\n  BB lines: ${lineStr}\n  DIVERGENCE: ` +
      diffs.map((d) => `${d.from}..${d.to}: PS ${d.ps === null ? "none" : "$" + (d.ps / 100).toFixed(2)} vs BB $${(d.bb / 100).toFixed(2)}`).join("; "),
  );
}
console.log(`\n[audit] ${clean} categories MATCH; ${reports.length} diverge\n`);
for (const r of reports) console.log(r + "\n");
EOF
bun "$CLAUDE_JOB_DIR/tmp/audit-budget-history.ts" 2>&1 | grep -v Warning | head -120

