cd ~/Documents/workspace/projects/envelope-os && cat > scripts/repair-budget-history.ts <<'EOF'
/**
 * One-off chronology repair from the 2026-08-12 audit (owner-approved):
 *
 *   bun run scripts/repair-budget-history.ts            # dry-run (report only)
 *   bun run scripts/repair-budget-history.ts --apply    # write (backs up first)
 *
 * For each envelope on the repair list (audit Patterns 1 + 6):
 *   - Fetch its PocketSmith budget eras (same series → eras collapse the
 *     backfill used), BRIDGING gaps between eras (a gap is a PS repeat
 *     artefact, not a real $0 budget: the earlier era extends to the day
 *     before the next).
 *   - Delete the legacy flat lines (effective_from < TAKEOVER 2026-06-01) and
 *     insert the eras in their place, clipped so every BudgetBuddy-AUTHORED
 *     version (from >= TAKEOVER) is preserved untouched. With no authored
 *     successor the final era stays open-ended (the current budget continues).
 *   - Envelopes with NO eras get a start-trim only: the flat line's start
 *     moves to the first mapped transaction's month (Pattern 6: "the category
 *     didn't exist in 2023").
 *   - Inserted eras carry the legacy line's cadence label; materialised
 *     months recompute afterwards (doctrine D4).
 *
 * Rental, Public Transport, Savings, and Gas are deliberately EXCLUDED
 * (owner decisions pending — see the audit report).
 */

import { copyFileSync, existsSync } from "node:fs";
import { buildContainer } from "../src/composition.ts";
import { installSecretLogRedaction } from "../src/server/redaction.ts";
import { PocketSmithClient } from "../src/ingest/client.ts";
import { erasFromSeries, findEraOverlap, type SeriesEvent, type BudgetEra } from "../src/ingest/budget-history.ts";
import { effectiveFromOf, effectiveToOf, previousDay } from "../src/budget/versions.ts";
import { findOverlaps, isTombstone } from "../src/budget/window.ts";
import type { BudgetTemplate } from "../src/domain/types.ts";
import type { EnvelopeStore } from "../src/envelope/ports.ts";
import type { BudgetStore } from "../src/budget/ports.ts";
import { BudgetService } from "../src/budget/service.ts";
import { EnvelopeService } from "../src/envelope/service.ts";

const APPLY = process.argv.includes("--apply");
const userId = process.env.PENNY_USER_ID ?? "local";
const TAKEOVER = "2026-06-01"; // BudgetBuddy became system of record here

/** Audit repair list: Pattern 1 (flattened history) + Pattern 6 (false starts). */
const REPAIR_NAMES = new Set([
  "Gym", "Phone", "Health Insurance", "Tolls", "Water", "Spotify", "Dog Food",
  "Doggy Day Care", "Presents", "Shopping", "Recreation", "Healthcare",
  "Internet", "Mortgage", "Electricity", "Car Insurance", "Car Rego",
  "Groceries",
  "Pocketsmith", "SMLSC Membership", "USLSC Membership", "Microsoft Onedrive",
  "Fairfax", "Mortgage Fee", "OC Fees", "Microsoft 365", "Netflix",
  "Council Rates", "Card Chasing",
]);

const container = await buildContainer();
const { secrets } = installSecretLogRedaction(container.secrets);
const store = container.store as BudgetStore & EnvelopeStore;

if (APPLY) {
  const dbPath = process.env.PENNY_SQLITE_PATH ?? `${process.env.HOME}/.penny/penny.db`;
  if (existsSync(dbPath)) {
    const backup = dbPath.replace(/\.db$/, `.pre-history-repair.db`);
    copyFileSync(dbPath, backup);
    if (existsSync(`${dbPath}-wal`)) copyFileSync(`${dbPath}-wal`, `${backup}-wal`);
    console.log(`[repair] backup written: ${backup}`);
  }
}

const client = await PocketSmithClient.forUser(secrets, userId);
const user = await client.getAuthenticatedUser();
const [mappings, template, envelopes, txs] = await Promise.all([
  store.listMappings(userId),
  store.listTemplate(userId),
  store.listEnvelopes(userId),
  store.listTransactions(userId),
]);
const targets = envelopes.filter((e) => REPAIR_NAMES.has(e.name));
const byName = new Map(targets.map((e) => [e.name, e.id]));
for (const n of REPAIR_NAMES) if (!byName.has(n)) console.log(`[repair] WARNING: no envelope named "${n}"`);
const envToCat = new Map<string, string[]>();
for (const m of mappings) {
  const arr = envToCat.get(m.envelopeId) ?? [];
  arr.push(m.categoryId);
  envToCat.set(m.envelopeId, arr);
}

const firstTxMonth = txs.reduce<string | null>((min, t) => (min === null || t.date < min ? t.date : min), null)!.slice(0, 7);
const events = await client.listEvents(user.id!, `${firstTxMonth}-01`, new Date().toISOString().slice(0, 10));
console.log(`[repair] ${events.length} events fetched`);
const byCategory = new Map<string, SeriesEvent[]>();
for (const ev of events) {
  const cid = ev.category?.id;
  if (cid === undefined || ev.date === undefined) continue;
  const arr = byCategory.get(String(cid)) ?? [];
  arr.push({
    seriesId: ev.series_id ?? 0,
    date: ev.date,
    amountCents: Math.abs(Math.round((ev.amount ?? 0) * 100)),
    repeatType: ev.repeat_type ?? "once",
    repeatInterval: ev.repeat_interval ?? 1,
  });
  byCategory.set(String(cid), arr);
}

/** Bridge gaps: each era extends to the day before the next era's start. */
function bridge(eras: BudgetEra[]): BudgetEra[] {
  const sorted = [...eras].sort((a, b) => a.from.localeCompare(b.from));
  return sorted.map((e, i) => {
    const next = sorted[i + 1];
    return { ...e, to: next ? previousDay(next.from) : e.to };
  });
}

const envSvc = new EnvelopeService(store as EnvelopeStore, { holdingEnvelopeId: null, nabCardAccountIds: [] }, { timezone: "Australia/Melbourne" });
const budget = new BudgetService(store, envSvc);

let repaired = 0;
for (const env of targets.sort((a, b) => a.name.localeCompare(b.name))) {
  const cats = envToCat.get(env.id) ?? [];
  const evs = cats.flatMap((c) => byCategory.get(c) ?? []);
  let eras = erasFromSeries(evs);
  if (findEraOverlap(eras)) {
    console.log(`\n${env.name}: SKIPPED — concurrent series overlap`);
    continue;
  }
  eras = bridge(eras);

  const live = template.filter((l) => l.envelopeId === env.id && !isTombstone(l));
  const authored = live.filter((l) => effectiveFromOf(l) >= TAKEOVER);
  const legacy = live.filter((l) => effectiveFromOf(l) < TAKEOVER);
  const boundary = authored.length > 0
    ? authored.map((l) => effectiveFromOf(l)).sort()[0]!
    : null;
  const clipEnd = boundary !== null ? previousDay(boundary) : null;

  if (legacy.length === 0) {
    console.log(`\n${env.name}: no legacy lines — nothing to repair`);
    continue;
  }
  const label = legacy[0]!.period ?? "monthly";

  let plan: { from: string; to: string | null; amountCents: number }[] = [];
  if (eras.length > 0) {
    for (const e of eras) {
      if (boundary !== null && e.from >= boundary) continue;
      let to = e.to;
      if (clipEnd !== null && (to === null || to > clipEnd)) to = clipEnd;
      plan.push({ from: e.from, to, amountCents: e.amountCents });
    }
    // The chronology must not end CLOSED with no successor when the envelope
    // previously had an open line: reopen the final planned era.
    if (boundary === null && plan.length > 0 && legacy.some((l) => effectiveToOf(l) === null)) {
      plan[plan.length - 1] = { ...plan[plan.length - 1]!, to: null };
    }
  } else {
    // Start-trim only: first mapped transaction's month.
    const firstTx = txs
      .filter((t) => t.categoryId !== null && cats.includes(t.categoryId))
      .reduce<string | null>((min, t) => (min === null || t.date < min ? t.date : min), null);
    if (firstTx === null) {
      console.log(`\n${env.name}: no eras and no transactions — left untouched`);
      continue;
    }
    for (const l of legacy) {
      let to = effectiveToOf(l);
      if (clipEnd !== null && (to === null || to > clipEnd)) to = clipEnd;
      plan.push({ from: `${firstTx.slice(0, 7)}-01`, to, amountCents: l.amountCents });
    }
  }
  if (plan.length === 0) {
    console.log(`\n${env.name}: plan empty (all eras at/after authored boundary) — legacy lines would just be deleted; SKIPPED for review`);
    continue;
  }

  console.log(`\n${env.name} (${env.id}) — boundary ${boundary ?? "none"}:`);
  for (const l of legacy) console.log(`  - delete ${effectiveFromOf(l)}→${effectiveToOf(l) ?? "…"} $${(l.amountCents / 100).toFixed(2)}/mo`);
  for (const p of plan) console.log(`  + insert ${p.from}→${p.to ?? "…"} $${(p.amountCents / 100).toFixed(2)}/mo (${label})`);
  for (const a of authored) console.log(`  = keep   ${effectiveFromOf(a)}→${effectiveToOf(a) ?? "…"} $${(a.amountCents / 100).toFixed(2)}/mo (authored)`);

  if (!APPLY) continue;

  await store.withTransaction(async () => {
    for (const l of legacy) await store.deleteTemplateLine(userId, l.id);
    const working: BudgetTemplate[] = (await store.listTemplate(userId)).filter((l) => l.envelopeId === env.id);
    for (const p of plan) {
      const line: BudgetTemplate = {
        id: crypto.randomUUID(),
        userId,
        envelopeId: env.id,
        amountCents: p.amountCents,
        period: label,
        effectiveFrom: p.from,
        effectiveTo: p.to,
      };
      await store.putTemplateLine(userId, line);
      working.push(line);
    }
    const overlaps = findOverlaps(working.filter((l) => !isTombstone(l)));
    if (overlaps.length > 0) throw new Error(`${env.name}: repair would overlap — aborted`);
    await store.appendEvent(userId, {
      id: crypto.randomUUID(),
      ts: Date.now(),
      actor: "repair-script",
      correlationId: crypto.randomUUID(),
      kind: "history.repair",
      payloadJson: JSON.stringify({ envelopeId: env.id, deleted: legacy.length, inserted: plan.length }),
    });
  });
  await (budget as unknown as { rederiveMaterialisedMonths: (u: string, e: string, t: BudgetTemplate[]) => Promise<void> })
    .rederiveMaterialisedMonths(userId, env.id, (await store.listTemplate(userId)));
  repaired++;
}
console.log(`\n[repair] ${APPLY ? "applied" : "planned"} for ${repaired || "0 (dry-run shows plans above)"}${APPLY ? " envelopes" : ""}`);
